import { useEffect, useState } from 'react';
import { cx } from '@/lib/cx.js';
import styles from './Ring.module.css';

/** The ring's size and stroke, in the SVG's own units (it is drawn at 36px). */
const SIZE = 36;
const STROKE = 3.5;
const RADIUS = (SIZE - STROKE) / 2;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

/**
 * How much of today is done, as a ring that fills: Today's hero. It carries
 * no number, so it can never show a wrong one; the hero's words say the
 * same thing for a screen reader, so the ring is hidden from it. It starts
 * at twelve o'clock and runs clockwise (the other way right to left), fills
 * from `from` (where it was last drawn) to `fraction`, and closes with one
 * pop and a tick. Under reduced motion it is drawn where it ends.
 */
export function Ring({
  fraction,
  from,
  className,
}: {
  fraction: number;
  /** Where the ring stood when it was last drawn, to fill from there; the same as `fraction` for no motion. */
  from?: number | undefined;
  className?: string | undefined;
}): React.JSX.Element {
  const [drawn, setDrawn] = useState(from ?? fraction);
  useEffect(() => {
    if (drawn === fraction) return;
    // One frame at the old value first, so the transition has somewhere to start.
    const frame = requestAnimationFrame(() => {
      setDrawn(fraction);
    });
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [drawn, fraction]);
  const closed = drawn >= 1;
  // The pop is for closing it, here and now; a ring that was already closed
  // when Today opened is simply drawn closed.
  const [wasOpen] = useState((from ?? fraction) < 1);
  return (
    <svg
      className={cx(styles.ring, closed && wasOpen && styles.closed, className)}
      viewBox={`0 0 ${String(SIZE)} ${String(SIZE)}`}
      aria-hidden="true"
      data-fraction={fraction.toFixed(2)}
    >
      <g className={styles.arc}>
        <circle className={styles.track} cx={SIZE / 2} cy={SIZE / 2} r={RADIUS} strokeWidth={STROKE} />
        <circle
          className={styles.fill}
          cx={SIZE / 2}
          cy={SIZE / 2}
          r={RADIUS}
          strokeWidth={STROKE}
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={CIRCUMFERENCE * (1 - drawn)}
        />
      </g>
      {closed && <path className={styles.tick} d="M12 18.5l4 4 8-8.5" />}
    </svg>
  );
}
