import { useEffect, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { serverNow } from '@/lib/serverClock.js';
import { CampaignArt } from './art/CampaignArt.js';
import { Seal } from './art/Seal.js';
import { fillCopy, offerCopyValues, type CampaignPick } from './campaign.js';
import { countdownView, eventStage } from './countdown.js';
import { OfferCountdown } from './OfferCountdown.js';
import { offerCloses, offerPrices } from './offer.js';
import { sendOfferEvent } from './offerEvents.js';
import { badgeWords, countdownLabel, offerBadgeKind, saleReference } from './planChoices.js';
import { useOfferWords } from './useOfferWords.js';
import { isMomentOffer } from './moment.js';
import { noteSellingShown } from './sellingSignals.js';
import { aroundAmount, isNight, nightStyle } from './night.js';
import { NightClosing } from './NightClosing.js';
import styles from './CampaignBanner.module.css';

/**
 * The campaign banner on Today (uiux offers spec §2.2, C3): one at a time,
 * after the hero, the session's one plan touch. Art on the hero ground,
 * a kicker, the campaign's headline, both prices together, the countdown in
 * minute steps, "See my offer" and "Not now", and "Don't remind me" in the
 * ••• menu. A priceless campaign (a greeting) has no price and no countdown.
 */
export function CampaignBanner({
  pick,
  onOpen,
  onNotNow,
  onStop,
  onEnded,
}: {
  pick: CampaignPick;
  onOpen: () => void;
  onNotNow: () => void;
  onStop: () => void;
  onEnded: () => void;
}): React.JSX.Element {
  const { creative, offer } = pick;
  const words = useOfferWords(offer);
  const [menu, setMenu] = useState(false);
  const [imageOk, setImageOk] = useState<boolean | undefined>(undefined);
  const hasArt = creative.images.some((image) => image.role === 'banner');
  const badge = offer === undefined ? creative.badge : offerBadgeKind(offer);
  const prices = offer === undefined || words === undefined ? undefined : offerPrices(offer, words);
  // A public sale's computed reduction, only when the server sent it.
  const reference = words === undefined ? undefined : saleReference(offer, words.fromStore === true)?.price;
  // A moment offer speaks its own words (§6): "Just for you", the price,
  // and its end in the countdown line; never a campaign's pressure.
  const moment = isMomentOffer(offer);
  // F5: the end words come from the offer's own latest closesAt.
  const values = offerCopyValues(offer, words, new Date(serverNow()));
  const title =
    (moment && words !== undefined ? t('moment.banner.title', { amount: words.first }) : undefined) ??
    fillCopy(creative.headline, values) ??
    (offer !== undefined && words !== undefined
      ? t('banner.titleEarly', { amount: words.first })
      : t('banner.title'));
  const line = moment ? undefined : fillCopy(creative.subline, values);
  useEffect(() => {
    noteSellingShown();
  }, []);
  const eventId = offer?.id;
  const campaign = { campaignId: creative.campaignId, variantId: creative.variantId };

  // Shown once the art has had its chance (loaded, failed or slow), so
  // the funnel knows whether the picture was there.
  const artSettled = !hasArt || imageOk !== undefined;
  useEffect(() => {
    if (eventId === undefined || !artSettled || offer === undefined) return;
    const closes = offerCloses(offer);
    const view =
      closes === undefined
        ? undefined
        : countdownView({
            closesAt: closes,
            now: serverNow(),
            surface: 'feed',
            liveSecondsFromHours: 0,
            style: moment ? 'moment' : creative.look.countdownStyle,
            calm: true,
          });
    sendOfferEvent(eventId, 'shown', 'today_banner', {
      ...campaign,
      ...(view === undefined ? {} : { countdownStage: eventStage(view.stage) }),
      ...(hasArt && imageOk !== undefined ? { imageOk } : {}),
    });
    // Once per banner on screen.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventId, artSettled]);

  if (isNight(creative) && offer !== undefined && words !== undefined) {
    const [beforeRenewal, afterRenewal] = aroundAmount((amount) => t('night.then', { amount }));
    return (
      <section
        className={cx(styles.banner, styles.night)}
        style={nightStyle(creative)}
        aria-labelledby="campaign-title"
      >
        <div className={styles.nBody}>
          <div className={styles.nText}>
            <span className={styles.nPill}>
              {badge === undefined ? t('paywall.kicker') : badgeWords(badge, offer)}
            </span>
            <h2 id="campaign-title" className={styles.nTitle}>
              {title}
            </h2>
            <NightClosing offer={offer} className={styles.nWhen} onEnded={onEnded} />
          </div>
          <div className={styles.nOffer}>
            <p className={styles.nPrice}>
              <b dir="ltr">{words.first}</b>
              <span>{t('night.firstYear')}</span>
            </p>
            <p className={styles.nThen}>
              {beforeRenewal}
              <bdi dir="ltr">{words.renewal}</bdi>
              {afterRenewal}
            </p>
            <div className={styles.nActions}>
              {menu ? (
                <button type="button" className={styles.nQuiet} onClick={onStop}>
                  {t('trial.dontRemind')}
                </button>
              ) : (
                <>
                  <button
                    type="button"
                    className={styles.nPrimary}
                    onClick={() => {
                      if (eventId !== undefined) sendOfferEvent(eventId, 'opened', 'today_banner', campaign);
                      onOpen();
                    }}
                  >
                    {creative.ctaLabel ?? t('banner.see')}
                  </button>
                  <button
                    type="button"
                    className={styles.nQuiet}
                    onClick={() => {
                      if (eventId !== undefined)
                        sendOfferEvent(eventId, 'dismissed', 'today_banner', campaign);
                      onNotNow();
                    }}
                  >
                    {creative.secondaryLabel ?? t('nudge.notNow')}
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
        <button
          type="button"
          className={cx(styles.more, styles.nMore)}
          aria-label={t('banner.more')}
          aria-expanded={menu}
          onClick={() => {
            setMenu((open) => !open);
          }}
        >
          <Icon name="more" size={20} weight={2} />
        </button>
      </section>
    );
  }

  return (
    <section className={cx(styles.banner, !hasArt && styles.noArt)} aria-labelledby="campaign-title">
      {hasArt && (
        <>
          <CampaignArt
            role="banner"
            creative={creative}
            sizes="(min-width: 1024px) 620px, calc(100vw - 40px)"
            className={styles.art}
            house={{ width: 1200, height: 800 }}
            onImage={setImageOk}
          />
          <span className={styles.scrim} aria-hidden="true" />
        </>
      )}
      <div className={styles.body}>
        <span className={styles.kicker}>
          <Seal size={14} />
          {badge === undefined ? t('paywall.kicker') : badgeWords(badge, offer)}
        </span>
        <h2 id="campaign-title" className={styles.title}>
          {title}
        </h2>
        {line !== undefined && <p className={styles.line}>{line}</p>}
        {prices !== undefined && (
          <p className={styles.line}>
            {reference !== undefined && (
              <>
                <s className={styles.reference} aria-hidden="true">
                  {reference}
                </s>
                <span className="sr-only">{t('pick.usualPrice', { amount: reference })} </span>{' '}
              </>
            )}
            <bdi>{prices.first}</bdi>, <bdi>{prices.then}</bdi>
          </p>
        )}
        {offer !== undefined && (
          <span className={styles.countdown}>
            <OfferCountdown
              closesAt={offer.closesAt}
              surface="feed"
              tone="hero"
              label={countdownLabel(badge)}
              style={moment ? 'moment' : creative.look.countdownStyle}
              onEnded={onEnded}
            />
          </span>
        )}
        <div className={styles.actions}>
          {menu ? (
            <button type="button" className={styles.quiet} onClick={onStop}>
              {t('trial.dontRemind')}
            </button>
          ) : (
            <>
              {(offer !== undefined || creative.ctaLabel !== undefined) && (
                <button
                  type="button"
                  className={styles.primary}
                  onClick={() => {
                    if (eventId !== undefined) sendOfferEvent(eventId, 'opened', 'today_banner', campaign);
                    onOpen();
                  }}
                >
                  {creative.ctaLabel ?? (moment ? t('moment.banner.see') : t('banner.see'))}
                </button>
              )}
              <button
                type="button"
                className={styles.quiet}
                onClick={() => {
                  if (eventId !== undefined) sendOfferEvent(eventId, 'dismissed', 'today_banner', campaign);
                  onNotNow();
                }}
              >
                {creative.secondaryLabel ?? t('nudge.notNow')}
              </button>
            </>
          )}
        </div>
      </div>
      <button
        type="button"
        className={styles.more}
        aria-label={t('banner.more')}
        aria-expanded={menu}
        onClick={() => {
          setMenu((open) => !open);
        }}
      >
        <Icon name="more" size={20} weight={2} />
      </button>
    </section>
  );
}
