import { useEffect, useState } from 'react';
import { t } from '@/i18n/index.js';
import { resolveTheme, useTheme } from '@/lib/theme.js';
import styles from '@/features/everywhere/NudgeCard.module.css';
import { CampaignImage } from './art/CampaignArt.js';
import { pickImage } from './art/pickImage.js';
import { SmallArt } from './art/Seal.js';
import { fillCopy, type CampaignPick } from './campaign.js';
import { OfferCountdown } from './OfferCountdown.js';
import { offerPrices } from './offer.js';
import { sendOfferEvent } from './offerEvents.js';
import { useOfferWords } from './useOfferWords.js';
import { noteSellingShown } from './sellingSignals.js';
import own from './AfterMilestoneCard.module.css';

/**
 * After a real milestone, on the next visit to Today (offer presentation
 * spec §3 row 6): one house card that connects the win to Pro, while the
 * campaign's offer is open and it asks for it (`afterMilestone`). Never on
 * the celebration itself, once per campaign, the session's one plan touch.
 * The campaign's square art (the house art without one), both prices, and
 * a countdown that says the date or the days, never seconds.
 */
export function AfterMilestoneCard({
  pick,
  onOpen,
  onNotNow,
  onEnded,
}: {
  pick: CampaignPick;
  onOpen: () => void;
  onNotNow: () => void;
  onEnded: () => void;
}): React.JSX.Element | null {
  const { creative, offer } = pick;
  const words = useOfferWords(offer);
  const theme = resolveTheme(useTheme((s) => s.theme));
  const direction = document.documentElement.dir === 'rtl' ? 'rtl' : 'ltr';
  const square = pickImage(creative.images, 'square', theme, direction);
  const [imageOk, setImageOk] = useState<boolean | undefined>(undefined);
  const eventId = offer?.id;
  const campaign = { campaignId: creative.campaignId, variantId: creative.variantId };
  const settled = square === undefined || imageOk !== undefined;
  useEffect(() => {
    noteSellingShown();
  }, []);
  useEffect(() => {
    if (eventId === undefined || !settled) return;
    sendOfferEvent(eventId, 'shown', 'after_milestone', {
      ...campaign,
      ...(square === undefined || imageOk === undefined ? {} : { imageOk }),
    });
    // Once, when it lands.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventId, settled]);
  if (offer === undefined || words === undefined) return null;
  const prices = offerPrices(offer, words);
  const title =
    fillCopy(creative.headline, { firstPeriodPrice: words.first, renewalPrice: words.renewal }) ??
    t('afterMilestone.title');
  return (
    <aside className={styles.card} aria-labelledby="after-milestone">
      <div className={styles.head}>
        <span className={own.art} aria-hidden="true">
          <SmallArt />
          {square !== undefined && <CampaignImage image={square} sizes="64px" onState={setImageOk} />}
        </span>
        <span className={styles.text}>
          <h2 id="after-milestone" className={styles.title}>
            {title}
          </h2>
          <p className={styles.line}>
            {prices.first}, {prices.then}
          </p>
          <span className={own.when}>
            <OfferCountdown closesAt={offer.closesAt} surface="feed" style="dateOnly" onEnded={onEnded} />
          </span>
        </span>
      </div>
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.primary}
          onClick={() => {
            sendOfferEvent(offer.id, 'opened', 'after_milestone', campaign);
            onOpen();
          }}
        >
          {creative.ctaLabel ?? t('banner.see')}
        </button>
        <button
          type="button"
          className={styles.quiet}
          onClick={() => {
            sendOfferEvent(offer.id, 'dismissed', 'after_milestone', campaign);
            onNotNow();
          }}
        >
          {t('nudge.notNow')}
        </button>
      </div>
    </aside>
  );
}
