import { Icon } from '@/components/ui/Icon.js';
import { setMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import type { UpdateLink } from '@/lib/updates.js';
import { useRememberedQuery } from '@/lib/useRememberedQuery.js';
import { STORE_BADGES } from '@/features/everywhere/stores.js';
import { loadOffer } from './offers.js';
import styles from './UpdateBanner.module.css';

/** The height the Microsoft Store badge is drawn at, as on Today's cards (NudgeCard's `BADGE`). */
const BADGE_HEIGHT = 40;

/**
 * One way to get the new version. The Microsoft Store is its own badge,
 * unmodified (real marks only); the site's download page is our button,
 * filled when it comes first and quiet when it is the second way.
 */
function Way({ link, first }: { link: UpdateLink; first: boolean }): React.JSX.Element {
  if (link.kind === 'microsoftStore') {
    const badge = STORE_BADGES.microsoftStore;
    const width = Math.round((badge.width / badge.height) * BADGE_HEIGHT);
    return (
      <a
        className={styles.badge}
        href={link.url}
        target="_blank"
        rel="noopener noreferrer"
        aria-label={t(badge.alt)}
      >
        <img className={styles.onLight} src={badge.src} alt="" width={width} height={BADGE_HEIGHT} />
        {badge.srcOnDark !== undefined && (
          <img className={styles.onDark} src={badge.srcOnDark} alt="" width={width} height={BADGE_HEIGHT} />
        )}
      </a>
    );
  }
  return (
    <a
      className={first ? styles.action : styles.quiet}
      href={link.url}
      target="_blank"
      rel="noopener noreferrer"
    >
      {t('update.get')}
    </a>
  );
}

/**
 * One line on Today when a newer build is out, for the copies nobody else
 * updates: a sideloaded Android build (the link opens Lexpad's Google Play
 * listing, which the shell hands to the Play app) and the desktop app (the
 * Mac or Windows download page, and on Windows the Microsoft Store, first
 * for a copy that came from it; the core hands every link to the browser).
 * "Not now" puts it away until the next version.
 */
export function UpdateBanner(): React.JSX.Element | null {
  // Remembered, so a return to Today draws the line with the page rather
  // than a moment later, pushing the page down.
  const offer = useRememberedQuery('updateOffer', loadOffer, []).value ?? null;
  if (offer === null) return null;
  return (
    <aside className={styles.banner} aria-live="polite">
      <p className={styles.text}>{t('update.available', { version: offer.version })}</p>
      <div className={styles.actions}>
        {offer.links.map((link, i) => (
          <Way key={link.kind} link={link} first={i === 0} />
        ))}
        <button
          type="button"
          className={styles.dismiss}
          aria-label={t('update.later')}
          onClick={() => {
            void setMeta('updateDismissed', offer.version);
          }}
        >
          <Icon name="close" size={16} weight={2} />
        </button>
      </div>
    </aside>
  );
}
