/**
 * The stores' own badges, as each store publishes them, for the cards that
 * offer an app or the extension. Real marks only (owner, 2026-10-17): never
 * a glyph of ours in a store's place.
 *
 * Sources, all unmodified apart from size:
 * - Google Play: Google's "Get it on Google Play" badge (English PNG from
 *   play.google.com/intl/en_us/badges), with only its transparent margin
 *   trimmed so it lines up with the others; the card keeps the clear space.
 * - App Store: Apple's black "Download on the App Store" badge (US-UK SVG,
 *   developer.apple.com/assets/elements/badges), shown at Apple's minimum
 *   of 40 px high; the black badge is the one Apple prefers on any ground.
 * - Microsoft Store, Edge Add-ons, Chrome Web Store, Firefox Add-ons: the
 *   files the site already uses (landing/site/assets, landing/CLAUDE.md
 *   "Platform marks"). Microsoft's dark badge on a light page and its
 *   light badge on a dark one, as Microsoft asks.
 *
 * Each badge is a link to its listing and nothing else. They are kept out
 * of the offline precache (`globIgnores` in vite.config.ts): a learner who
 * never sees a card never downloads one.
 */
import type { MessageKey } from '@/i18n/index.js';
import appStoreBadge from './badges/badge-app-store-v1.svg';
import chromeBadge from './badges/badge-chrome-web-store-v1.png';
import edgeBadge from './badges/badge-edge-addons-v1.png';
import firefoxBadge from './badges/badge-firefox-addons-v1.svg';
import playBadge from './badges/badge-google-play-v1.png';
/**
 * The Google Play listing as a QR code, for a computer's card: generated once
 * (qrcode 1.5.4, error correction M, its own white quiet zone) and kept as a
 * file, so nothing is fetched to draw it. It encodes PLAY_URL with
 * `referrer=utm_source=app.lexpad.app&utm_medium=qr&utm_campaign=android-page`,
 * so Play Console can count its installs. A new address means a new file.
 */
export { default as PLAY_QR } from './badges/badge-qr-google-play-v1.svg';
import msStoreDark from './badges/badge-microsoft-store-dark-v1.svg';
import msStoreLight from './badges/badge-microsoft-store-light-v1.svg';
import chromeLogo from './badges/logo-chrome-v1.svg';
import edgeLogo from './badges/logo-edge-v1.svg';
import firefoxLogo from './badges/logo-firefox-v1.svg';
import type { PhoneStore } from './apps.js';

export type StoreId = PhoneStore | 'microsoftStore' | 'chrome' | 'edge' | 'firefox';

export interface StoreBadge {
  /** What the badge says, which is also the link's name. */
  alt: MessageKey;
  /** The badge for a light page. */
  src: string;
  /** The badge for a dark page, when the store makes one. */
  srcOnDark?: string;
  /** The file's own proportions, so the space is held before it loads. */
  width: number;
  height: number;
  /**
   * Shown taller than the 40 px the phone badges use. The browsers' store
   * badges are white tiles with their own border and small type, so at 40 px
   * they read fainter than the black phone badges; they are only ever shown
   * alone on the extension card, never beside those.
   */
  tall?: boolean;
}

export const STORE_BADGES: Record<StoreId, StoreBadge> = {
  play: { alt: 'getapp.badge.play', src: playBadge, width: 564, height: 168 },
  appStore: { alt: 'getapp.badge.appStore', src: appStoreBadge, width: 120, height: 40 },
  microsoftStore: {
    alt: 'getapp.badge.microsoftStore',
    src: msStoreDark,
    srcOnDark: msStoreLight,
    width: 161,
    height: 44,
  },
  chrome: { alt: 'getapp.badge.chrome', src: chromeBadge, width: 496, height: 150, tall: true },
  edge: { alt: 'getapp.badge.edge', src: edgeBadge, width: 634, height: 168, tall: true },
  firefox: { alt: 'getapp.badge.firefox', src: firefoxBadge, width: 172, height: 60, tall: true },
};

/** The browsers' own logos, for the extension card's tile. */
export const BROWSER_LOGOS: Record<'chrome' | 'edge' | 'firefox', string> = {
  chrome: chromeLogo,
  edge: edgeLogo,
  firefox: firefoxLogo,
};
