import { useState } from 'react';
import { accountAddress } from '@/features/auth/hiddenEmail.js';
import { auth as authApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { setMeta } from '@/db/schema.js';
import { rememberRead } from '@/lib/readMemory.js';
import { t } from '@/i18n/index.js';
import { useAuth } from './session.js';
import { SNOOZE_MS, SNOOZE_READ, useUnconfirmedCards, useVerifyWanted } from './verifyNotice.js';
import styles from './VerifyBanner.module.css';

/**
 * A quiet row on Today while the address is unconfirmed (uiux
 * 2026-10-22-today-first-visit S4, owner-approved 22 Oct 2026): what is
 * waiting, the allowance said as its number rather than as a threat ("to
 * keep using AI cards"), and the one action that helps. It goes on its own
 * once the profile refresh sees the confirmation, and can be put away for a
 * day by someone who cannot reach their inbox right now. Today draws it
 * under the day's plan, never above it, and only when it is the one notice
 * of the visit (`TodayNotice`).
 */
export function VerifyBanner(): React.JSX.Element | null {
  const user = useAuth((state) => state.user);
  const refreshUser = useAuth((state) => state.refreshUser);
  const wanted = useVerifyWanted();
  const cards = useUnconfirmedCards();
  const [note, setNote] = useState<string | undefined>();
  const [busy, setBusy] = useState(false);
  const [snoozed, setSnoozed] = useState(false);

  if (user === null || wanted !== true || snoozed) return null;

  const snooze = (): void => {
    const until = Date.now() + SNOOZE_MS;
    setSnoozed(true);
    rememberRead(SNOOZE_READ, until);
    void setMeta('verifySnoozedUntil', until);
  };

  const resend = (): void => {
    setBusy(true);
    authApi
      .resendVerification()
      .then(() => {
        setNote(t('auth.verifyResent'));
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'offline')) setNote(t('error.offline'));
        else if (cause instanceof ApiError && cause.code === 'rate_limited')
          setNote(t('auth.verifyResendLater'));
        else if (cause instanceof ApiError && cause.code === 'mail_unavailable')
          setNote(t('auth.verifyMailUnavailable'));
        else if (cause instanceof ApiError && cause.code === 'already_verified') void refreshUser();
        else setNote(t('error.generic'));
      })
      .finally(() => {
        setBusy(false);
      });
  };

  return (
    <aside className={styles.banner} aria-labelledby="verify-title">
      <span className={styles.disc} aria-hidden="true">
        <Icon name="mail" size={18} weight={1.9} />
      </span>
      <div className={styles.body}>
        <p id="verify-title" className={styles.title}>
          {t('auth.verifyBanner')}
        </p>
        <p className={styles.text} aria-live="polite">
          {note ??
            (cards === null
              ? t('auth.verifyBannerLineNoGate', { email: accountAddress(user) })
              : t('auth.verifyBannerLine', { email: accountAddress(user), count: cards }))}
        </p>
        {note === undefined && (
          <button type="button" className={styles.action} onClick={resend} disabled={busy}>
            {t('auth.verifyResend')}
          </button>
        )}
      </div>
      <button type="button" className={styles.dismiss} onClick={snooze} aria-label={t('auth.verifyLater')}>
        <Icon name="close" size={16} weight={2} />
      </button>
    </aside>
  );
}
