/**
 * Today's one notice (uiux 2026-10-22-today-first-visit S1, owner-approved
 * 22 Oct 2026). Up to three lines used to stand above the day's plan at once
 * (confirm your e-mail, the phone's reminder offer, the browser's) and on day
 * 2 they pushed "Start session" down onto the tab bar. Now the plan comes
 * first, and under it at most one of them a visit.
 *
 * Which one: a reminder offer when it wants this day (each is asked once, on
 * a day it decides, and would otherwise lose that day), else the e-mail row,
 * which is there every day until the address is confirmed or put away for
 * the day. The choice is held for the visit, so one never replaces another
 * on screen. Nothing is decided or marked shown for the ones not drawn.
 */
import { useState } from 'react';
import { VerifyBanner } from '@/features/auth/VerifyBanner.js';
import { useVerifyWanted } from '@/features/auth/verifyNotice.js';
import { TodayWebReminder } from '@/features/reminder/WebReminderOffer.js';
import { offersOnToday } from '@/features/reminder/webOffer.js';
import { useRememberedQuery } from '@/lib/useRememberedQuery.js';
import { ReminderBanner } from './ReminderBanner.js';
import { shouldOffer } from './offers.js';
import { pickNotice, type NoticeKind } from './notice.js';

export function TodayNotice(): React.JSX.Element | null {
  // The same remembered reads the notices make themselves, so each is read
  // once a run and a return to Today knows at once.
  const webReminder = useRememberedQuery('webReminderLine', offersOnToday, []).value;
  const reminder = useRememberedQuery('reminderOffer', shouldOffer, []).value;
  const verify = useVerifyWanted();
  const pick = pickNotice({ webReminder, reminder, verify });
  const [held, setHeld] = useState<NoticeKind | undefined>(undefined);
  if (held === undefined && pick !== undefined) setHeld(pick);
  switch (held) {
    case 'webReminder':
      return <TodayWebReminder />;
    case 'reminder':
      return <ReminderBanner />;
    case 'verify':
      return <VerifyBanner />;
    default:
      return null;
  }
}
