/**
 * Which of Today's notices is the visit's one (TodayNotice.tsx), as a pure
 * rule for the screen and its tests (uiux 2026-10-22-today-first-visit S1).
 */
export type NoticeKind = 'webReminder' | 'reminder' | 'verify' | 'none';

/** The notice for these wishes, or undefined while one of them is still unknown. Pure. */
export function pickNotice(wants: {
  webReminder: boolean | undefined;
  reminder: boolean | undefined;
  verify: boolean | undefined;
}): NoticeKind | undefined {
  if (wants.webReminder === undefined || wants.reminder === undefined) return undefined;
  if (wants.webReminder) return 'webReminder';
  if (wants.reminder) return 'reminder';
  if (wants.verify === undefined) return undefined;
  return wants.verify ? 'verify' : 'none';
}
