import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { lastDayOf } from './offer.js';
import { TRIAL_ENDING_DAYS } from './trial.js';
import styles from './KeepPro.module.css';

const DAY = 86_400_000;

/**
 * The trial's timeline on the day-0 takeover (marketer §6.1, uiux §2.9):
 * today Pro is on with no card; a few days before the end we remind (the
 * trial e-mail goes `TRIAL_ENDING_DAYS` before); at the end, back to Free
 * with nothing charged. No price on this screen.
 */
export function TrialTimeline({ endsAt, now }: { endsAt: Date; now: Date }): React.JSX.Element {
  const remindAt = new Date(endsAt.getTime() - TRIAL_ENDING_DAYS * DAY);
  return (
    <ol className={cx(styles.timeline, styles.timelinePlain)}>
      <li>
        <span className={cx(styles.dot, styles.dotNow)} aria-hidden="true">
          <Icon name="check" size={16} weight={2.2} />
        </span>
        <span className={styles.when}>{t('trialStart.today')}</span>
        <p className={styles.what}>{t('trialStart.todayLine')}</p>
      </li>
      <li>
        <span className={cx(styles.dot, styles.dotGold)} aria-hidden="true">
          <Icon name="bell" size={15} />
        </span>
        <span className={styles.when}>{lastDayOf(new Date(remindAt.getTime() + 1), now)}</span>
        <p className={styles.what}>{t('trialStart.remindLine')}</p>
      </li>
      <li>
        <span className={styles.dot} aria-hidden="true">
          <Icon name="clock" size={15} />
        </span>
        <span className={styles.when}>{lastDayOf(endsAt, now)}</span>
        <p className={styles.what}>{t('trialStart.endLine')}</p>
      </li>
    </ol>
  );
}
