import { Icon } from '@/components/ui/Icon.js';
import { setMeta } from '@/db/schema.js';
import { setReminder } from '@/db/mutations.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { useRememberedQuery } from '@/lib/useRememberedQuery.js';
import { DEFAULT_REMINDER_TIME, startReminder } from '@/features/settings/reminders.js';
import { syncSoon } from '@/sync/store.js';
import { shouldOffer } from './offers.js';
import styles from './UpdateBanner.module.css';

/**
 * One line on Today asking to turn the daily reminder on, for people who
 * set the app up before the reminder was on by default or switched it off
 * then. Testers who never found the switch were the ones who stopped coming
 * back (2026-10-02). "Not now" puts it away for good; Settings still has it.
 */
export function ReminderBanner(): React.JSX.Element | null {
  // Remembered, so a return to Today draws the line with the page rather
  // than a moment later, pushing the page down.
  const offer = useRememberedQuery('reminderOffer', shouldOffer, []).value ?? false;
  if (!offer) return null;
  return (
    <aside className={styles.banner} aria-live="polite">
      <p className={styles.text}>{t('reminderOffer.text', { time: DEFAULT_REMINDER_TIME })}</p>
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.action}
          onClick={() => {
            void setReminder(DEFAULT_REMINDER_TIME, localTimeZone()).then(() => {
              void syncSoon();
              void startReminder().catch(() => undefined);
            });
          }}
        >
          {t('reminderOffer.on')}
        </button>
        <button
          type="button"
          className={styles.dismiss}
          aria-label={t('reminderOffer.later')}
          onClick={() => {
            void setMeta('reminderOfferDismissed', true);
          }}
        >
          <Icon name="close" size={16} weight={2} />
        </button>
      </div>
    </aside>
  );
}
