import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { factLines, useTrialFacts } from '@/features/billing/facts.js';
import { openOffer, trialDaysLeft, type Offer } from '@/features/billing/offer.js';
import { sendOfferEvent } from '@/features/billing/offerEvents.js';
import { useBilling } from '@/features/billing/state.js';
import { trialDate, type TrialCardKind } from '@/features/billing/trial.js';
import { settingsPath } from '@/features/settings/paths.js';
import styles from '@/features/everywhere/NudgeCard.module.css';
import { Seal } from '@/features/billing/art/Seal.js';
import { OfferCountdown } from '@/features/billing/OfferCountdown.js';
import { countdownLabel, offerBadgeKind } from '@/features/billing/planChoices.js';
import { receiptRows, trialLengthDays, type ReceiptRow } from '@/features/billing/receipt.js';
import { perDay } from '@/features/billing/anchors.js';
import { useOfferWords } from '@/features/billing/useOfferWords.js';
import { cx } from '@/lib/cx.js';
import trialStyles from './TrialCard.module.css';
import { markTrialCardShown, type TrialMoments } from './useTrial.js';

/** At most this many rows of what Pro did on the end card (uiux §2.9). */
const MINI_RECEIPT_ROWS = 3;

/** The countdown's label: the offer's badge words, or plain. */
function offerBadgeLabel(offer: Offer): string | undefined {
  const kind = offerBadgeKind(offer);
  return countdownLabel(kind);
}

/**
 * The Pro trial's one card on Today (trial-offers design 2026-10-13, §2.3),
 * in the house shape for suggestions:
 *
 * - **meetLex** (day 2): "Lex knows your words", with two of the learner's
 *   own words, and "Ask Lex";
 * - **midway** (days 3–6): Pro until a date, and one thing not tried yet;
 * - **week** (day 7): "A week of Pro" with what Pro did, "Keep Pro", and
 *   with an open yearly offer its two prices in the seller's words, the
 *   price per day when the figure shown is in hand, and its countdown
 *   (sales plan A, 2026-10-24);
 * - **ended** (the first visit after): "Back on Free, with everything you
 *   made", the Lex questions, the early price if it is still open.
 *
 * Every card has Not now and, behind ⋯, "Don't remind me", which stops
 * every Pro reminder on the account. "Keep Pro" opens the Plan page; only
 * the week card names a price. Being on screen once is what makes it once.
 */
export function TrialCard({
  kind,
  trial,
  words,
}: {
  kind: TrialCardKind;
  trial: TrialMoments;
  /** Two of the learner's own words, newest first, for "Meet Lex". */
  words: readonly string[];
}): React.JSX.Element | null {
  const navigate = useNavigate();
  const state = trial.state;
  const setReminders = useBilling((s) => s.setReminders);
  const refresh = useBilling((s) => s.refresh);
  const facts = useTrialFacts((s) => s.facts);
  const ensureFacts = useTrialFacts((s) => s.ensure);
  const [menu, setMenu] = useState(false);
  const [failed, setFailed] = useState(false);
  const endedKey = trial.ended?.key;
  const offer = openOffer(state, trial.now);
  const offerId = offer?.id;
  // The week card's price: a yearly offer for one year only, in the seller's words.
  const priced = kind === 'week' && offer?.planId === 'pro_yearly' && offer.periods === 1 ? offer : undefined;
  const offerWords = useOfferWords(priced);

  useEffect(() => {
    markTrialCardShown(kind, endedKey);
  }, [kind, endedKey]);
  useEffect(() => {
    if (kind === 'week' || kind === 'ended') ensureFacts();
  }, [kind, ensureFacts]);
  useEffect(() => {
    if (offerId !== undefined) sendOfferEvent(offerId, 'shown', 'today_card');
  }, [offerId]);

  const titleId = `trial-${kind}`;
  const toPlan = (): void => {
    trial.answer(kind);
    if (offerId !== undefined) sendOfferEvent(offerId, 'opened', 'today_card');
    void navigate(settingsPath('plan'));
  };
  const notNow = (): void => {
    if (offerId !== undefined) sendOfferEvent(offerId, 'dismissed', 'today_card');
    trial.answer(kind, 'notNow');
  };
  const stop = (): void => {
    setFailed(false);
    setReminders(false)
      .then(() => {
        if (offerId !== undefined) sendOfferEvent(offerId, 'dismissed', 'today_card');
        trial.answer(kind, 'notNow');
      })
      .catch(() => {
        setFailed(true);
      });
  };

  const icon: IconName = 'sparkles';
  let seal = false;
  let rows: ReceiptRow[] = [];
  let title: string;
  let lines: string[];
  let action: { label: string; run: () => void };
  switch (kind) {
    case 'meetLex': {
      const [one, two] = words;
      if (one === undefined) return null;
      title = t('trial.meetLexTitle');
      lines = [
        two === undefined
          ? t('trial.meetLexLineSingle', { word1: one })
          : t('trial.meetLexLine', { word1: one, word2: two }),
      ];
      action = {
        label: t('trial.meetLexAction'),
        run: () => {
          trial.answer(kind);
          void navigate('/assistant');
        },
      };
      break;
    }
    case 'midway': {
      const running = trial.running;
      if (running === undefined) return null;
      // The Pro thing not tried yet: a text for somebody who never pasted
      // one, Lex for somebody who has.
      const read = !trial.pasted;
      title = t('trial.midwayTitle', { date: trialDate(running.endsAt, trial.now) });
      lines = [read ? t('trial.midwayReadLine') : t('trial.midwayLexLine')];
      action = {
        label: read ? t('trial.midwayRead') : t('trial.midwayLex'),
        run: () => {
          trial.answer(kind);
          void navigate(read ? '/read' : '/assistant');
        },
      };
      break;
    }
    case 'week': {
      const running = trial.running;
      if (running === undefined) return null;
      const did = factLines(facts);
      const lex = running.lexQuestions;
      title = t('trial.weekTitle');
      lines =
        did.length > 0
          ? [did.slice(0, 2).join('. ') + '.']
          : lex > 0
            ? [`${t('plan.facts.lex', { count: lex })}.`]
            : [t('trial.weekNone', { count: Math.max(1, trialDaysLeft(running.endsAt, trial.now)) })];
      if (priced !== undefined && offerWords !== undefined) {
        // The per-day figure only from the amount actually written.
        const day =
          offerWords.fromStore === true
            ? undefined
            : perDay({ amountMinor: priced.firstPeriod.amountMinor, currency: priced.firstPeriod.currency });
        lines.push(
          day === undefined
            ? t('trial.weekPricePlain', { amount: offerWords.first, renewal: offerWords.renewal })
            : t('trial.weekPrice', { amount: offerWords.first, perDay: day, renewal: offerWords.renewal }),
        );
      }
      action = { label: t('trial.keepPro'), run: toPlan };
      break;
    }
    case 'ended': {
      // "Your 14 days of Pro" (uiux §2.9, marketer §6.4): a receipt-like
      // card, an S-size moment with the gold seal, no confetti.
      seal = true;
      const asked = trial.ended?.lexQuestions ?? 0;
      const length = trialLengthDays(facts);
      rows = receiptRows(facts).slice(0, MINI_RECEIPT_ROWS);
      title = length === undefined ? t('trial.endedTitle') : t('trialEnd.title', { count: length });
      lines =
        length === undefined
          ? [
              [t('trial.endedLine'), asked > 0 ? t('trial.endedLex', { count: asked }) : undefined]
                .filter((part) => part !== undefined)
                .join(' '),
            ]
          : [t('trialEnd.line')];
      action = { label: t('trial.keepPro'), run: toPlan };
      break;
    }
  }

  return (
    <aside className={styles.card} aria-labelledby={titleId}>
      <div className={styles.head}>
        <span className={cx(styles.icon, seal && trialStyles.sealTile)} aria-hidden="true">
          {seal ? <Seal size={24} /> : <Icon name={icon} size={20} weight={1.9} />}
        </span>
        <span className={styles.text}>
          <h2 id={titleId} className={styles.title}>
            {title}
          </h2>
          {lines.map((line) => (
            <p key={line} className={styles.line}>
              {line}
            </p>
          ))}
        </span>
        <button
          type="button"
          className={styles.more}
          aria-label={t('nudge.more')}
          aria-expanded={menu}
          onClick={() => {
            setMenu((open) => !open);
          }}
        >
          <Icon name="more" size={18} weight={2} />
        </button>
      </div>
      {rows.length > 0 && (
        <ul className={trialStyles.mini}>
          {rows.map((row) => (
            <li key={row.label}>
              <Icon name={row.icon} size={16} />
              <span>{row.label}</span>
              <b>{row.count}</b>
            </li>
          ))}
        </ul>
      )}
      {(kind === 'ended' || (kind === 'week' && priced !== undefined && offerWords !== undefined)) &&
        offer !== undefined && (
          <div className={trialStyles.meta}>
            <OfferCountdown
              closesAt={offer.closesAt}
              surface="feed"
              label={offerBadgeLabel(offer)}
              style={offer.creative?.look.countdownStyle ?? 'auto'}
              onEnded={() => {
                void refresh();
              }}
            />
          </div>
        )}
      <div className={styles.actions}>
        {menu ? (
          <button type="button" className={styles.quiet} onClick={stop}>
            {t('trial.dontRemind')}
          </button>
        ) : (
          <>
            <button type="button" className={styles.primary} onClick={action.run}>
              {action.label}
            </button>
            <button type="button" className={styles.quiet} onClick={notNow}>
              {t('nudge.notNow')}
            </button>
          </>
        )}
      </div>
      {failed && (
        <p className={styles.note} role="status">
          {t('plan.remind.failed')}
        </p>
      )}
    </aside>
  );
}
