import { useEffect, useRef } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import styles from '@/features/everywhere/NudgeCard.module.css';
import { markInviteShown } from './state.js';

/**
 * Today's one-time offer to invite friends, after a good moment (a 7-day
 * streak, the first mastered word). It takes the same place as every other
 * suggestion on Today (`NudgeSlot`'s fallback), so it is never beside
 * another card, and never a pop-up. Shown once: on screen is spent.
 */
export function InviteCard({
  days,
  onInvite,
  onNotNow,
}: {
  days: number;
  onInvite: () => void;
  onNotNow: () => void;
}): React.JSX.Element {
  const marked = useRef(false);
  useEffect(() => {
    if (marked.current) return;
    marked.current = true;
    void markInviteShown();
  }, []);
  return (
    <aside className={styles.card} aria-labelledby="invite-card-title">
      <div className={styles.head}>
        <span className={styles.icon} aria-hidden="true">
          <Icon name="gift" size={20} weight={1.9} />
        </span>
        <span className={styles.text}>
          <h2 id="invite-card-title" className={styles.title}>
            {t('invite.cardTitle')}
          </h2>
          <p className={styles.line}>{t('invite.cardLine', { days })}</p>
        </span>
      </div>
      <div className={styles.actions}>
        <button type="button" className={styles.primary} onClick={onInvite}>
          {t('invite.cardAction')}
        </button>
        <button type="button" className={styles.quiet} onClick={onNotNow}>
          {t('nudge.notNow')}
        </button>
      </div>
    </aside>
  );
}
