/**
 * Campaigns: the look and placement of an offer, or a priceless greeting
 * (offer presentation spec 2026-10-13, §3; the server resolves the one
 * variant for this account and locale, `ResolvedCreative`). This file only
 * decides whether a surface may show it here and now, and fills the
 * campaign's words with data. Pure, so every cap has a test.
 *
 * Caps held here, on this device (the server keeps the funnel):
 * - pushed surfaces never in the account's first `CAMPAIGN_QUIET_DAYS`,
 *   never to somebody who said "Don't remind me", never where this client
 *   cannot sell an offer, never during the trial (its own cards own Today),
 *   except a seasonal sale that says `surfaces.inTrial` (Black Friday plan
 *   F2), which takes the place of the trial's soft tips only;
 * - the Today banner: "Not now" hides it for the campaign's `snoozeDays`,
 *   and it may come back once in the last 24 hours when the campaign says;
 * - full screen: once per campaign, at most one every
 *   `FULLSCREEN_EVERY_DAYS`, never on a day that already had a big moment.
 */
import type { ApiBillingState, ApiResolvedCreative } from '@/api/types.js';
import type { StoredOfferNotes } from '@/db/schema.js';
import type { Offer } from './offer.js';
import { isMomentOffer, localDayNumber } from './moment.js';
import { closingDate, closingTime } from './night.js';

const HOUR = 3_600_000;
const DAY = 24 * HOUR;

/** No pushed campaign surface in an account's first days (§3: "not in the first 2 days"). */
export const CAMPAIGN_QUIET_DAYS = 2;
/** At most one full-screen offer this often, across campaigns (§3). */
export const FULLSCREEN_EVERY_DAYS = 14;
/** The banner may come back once inside this last stretch (§3: "once in the last 24 h"). */
export const BANNER_RETURN_HOURS = 24;

export type Creative = ApiResolvedCreative;

/** Everything a surface's choice needs. */
export interface CampaignSignals {
  now: Date;
  /** When the account was made; unknown reads as too new. */
  createdAt: Date | undefined;
  notes: StoredOfferNotes;
  /** This client may sell (the offer's price is real here). */
  sells: boolean;
  /** A running trial: its own cards own Today. */
  inTrial: boolean;
  /** Today's big moment was already taken (BIG_PER_DAY). */
  bigToday: boolean;
}

/** What a campaign surface presents: an offer with its creative, or a priceless campaign. */
export interface CampaignPick {
  creative: Creative;
  /** Present for a priced campaign; absent for a greeting or a feature promotion. */
  offer?: Offer | undefined;
}

function pastQuiet(signals: CampaignSignals): boolean {
  if (signals.createdAt === undefined) return false;
  return signals.now.getTime() - signals.createdAt.getTime() >= CAMPAIGN_QUIET_DAYS * DAY;
}

/**
 * Whether the open offer's campaign may also show during the Pro trial: a
 * seasonal sale that says so (Black Friday plan F2). The trial's own last
 * week and end cards still win over it (`SALE_REPLACES_TRIAL_CARDS` lists the cards it may replace).
 */
export function showsInTrial(offer: Offer | undefined): boolean {
  const creative = offer?.creative;
  return creative?.kind === 'seasonal_sale' && creative.surfaces.inTrial === true;
}

/** The trial cards a sale's banner may take the place of: the soft tips, never the last week or the end. */
export const SALE_REPLACES_TRIAL_CARDS = ['meetLex', 'midway'] as const;

function stillOn(creative: Creative, now: Date): boolean {
  const ends = creative.endsAt === undefined ? undefined : Date.parse(creative.endsAt);
  return ends === undefined || Number.isNaN(ends) || ends > now.getTime();
}

/**
 * The campaign the pushed surfaces may speak of: the open offer's creative
 * (a priced campaign), else the plan's own priceless campaign. A priced
 * campaign needs a client that sells; nothing is pushed to somebody who
 * said "Don't remind me".
 */
export function pushedCampaign(
  state: ApiBillingState | null,
  offer: Offer | undefined,
  signals: CampaignSignals,
): CampaignPick | undefined {
  if (
    state === null ||
    state.offerReminders === false ||
    (signals.inTrial && !showsInTrial(offer)) ||
    !pastQuiet(signals)
  )
    return undefined;
  if (offer?.creative !== undefined && signals.sells && stillOn(offer.creative, signals.now)) {
    return { creative: offer.creative, offer };
  }
  // A moment offer has its Today banner whether or not a campaign dresses
  // it (moment offer §5 M7): the house look, its own words.
  if (offer !== undefined && isMomentOffer(offer) && signals.sells) {
    return { creative: momentHouse(offer), offer };
  }
  const priceless = state.campaign;
  if (priceless !== undefined && stillOn(priceless, signals.now)) return { creative: priceless };
  return undefined;
}

/** Whether the Today banner shows for this campaign now. */
export function bannerShows(pick: CampaignPick | undefined, signals: CampaignSignals): boolean {
  if (pick === undefined) return false;
  const banner = pick.creative.surfaces.todayBanner;
  if (!banner.on) return false;
  const id = pick.creative.campaignId;
  const notes = signals.notes;
  if (notes.bannerDone?.includes(id) === true) return false;
  // A moment offer's banner: at most one day's showing a day (§5 M7).
  if (isMomentOffer(pick.offer) && notes.bannerDay?.[id] === localDayNumber(signals.now)) return false;
  const snoozed = notes.bannerSnoozedUntil?.[id];
  const until = snoozed === undefined ? Number.NaN : Date.parse(snoozed);
  if (Number.isNaN(until) || until <= signals.now.getTime()) return true;
  // Put away: back once in the last day, when the campaign says so.
  if (!banner.returnLastDay || notes.bannerReturned?.includes(id) === true) return false;
  const closes = pick.offer === undefined ? undefined : Date.parse(pick.offer.closesAt);
  return closes !== undefined && closes - signals.now.getTime() <= BANNER_RETURN_HOURS * HOUR;
}

/** Whether the full-screen offer opens now: once per campaign, one a fortnight, never on a big day. */
export function fullscreenShows(pick: CampaignPick | undefined, signals: CampaignSignals): boolean {
  if (pick?.offer === undefined || !pick.creative.surfaces.fullscreen || signals.bigToday) return false;
  const notes = signals.notes;
  if (notes.fullscreenShown?.includes(pick.creative.campaignId) === true) return false;
  const last = notes.fullscreenAt === undefined ? Number.NaN : Date.parse(notes.fullscreenAt);
  return Number.isNaN(last) || signals.now.getTime() - last >= FULLSCREEN_EVERY_DAYS * DAY;
}

/**
 * How fresh a milestone must be for the next visit to Today to connect it to
 * Pro (§3 row 6: "the next Today render after a milestone"): within the day,
 * so a milestone from last week never surfaces as if it were just now.
 */
export const MILESTONE_FRESH_HOURS = 24;

/** Whether the after-milestone card shows: a fresh milestone, an open offer that asks for it, once per campaign. */
export function afterMilestoneShows(pick: CampaignPick | undefined, signals: CampaignSignals): boolean {
  if (pick?.offer === undefined || !pick.creative.surfaces.afterMilestone) return false;
  const notes = signals.notes;
  if (notes.afterMilestoneShown?.includes(pick.creative.campaignId) === true) return false;
  const at = notes.milestoneAt === undefined ? Number.NaN : Date.parse(notes.milestoneAt);
  if (Number.isNaN(at)) return false;
  const since = signals.now.getTime() - at;
  return since >= 0 && since <= MILESTONE_FRESH_HOURS * HOUR;
}

/** The notes once the after-milestone card was shown (once per campaign). */
export function noteAfterMilestone(notes: StoredOfferNotes, creative: Creative): StoredOfferNotes {
  const shown = notes.afterMilestoneShown ?? [];
  return shown.includes(creative.campaignId)
    ? notes
    : { ...notes, afterMilestoneShown: [...shown, creative.campaignId] };
}

/** The notes after "Not now" on the banner: hidden for the campaign's snooze days. */
export function snoozeBanner(notes: StoredOfferNotes, creative: Creative, now: Date): StoredOfferNotes {
  const until = new Date(now.getTime() + creative.surfaces.todayBanner.snoozeDays * DAY).toISOString();
  return { ...notes, bannerSnoozedUntil: { ...notes.bannerSnoozedUntil, [creative.campaignId]: until } };
}

/** The notes once a banner was put on screen today (a moment offer's: once a day). */
export function noteBannerDay(notes: StoredOfferNotes, creative: Creative, now: Date): StoredOfferNotes {
  return { ...notes, bannerDay: { ...notes.bannerDay, [creative.campaignId]: localDayNumber(now) } };
}

/**
 * The house look of a moment offer no campaign dresses: its own id (so its
 * caps are its own), the Today banner on, "Not now" putting it away until
 * the last day, live seconds only in the last 24 hours (§10.1), no full
 * screen, no after-milestone card (the moment card is its own), and no
 * words of its own: the banner says the moment offer's words.
 */
export const MOMENT_SNOOZE_DAYS = 3;

export function momentHouse(offer: Offer): Creative {
  return {
    campaignId: offer.id,
    variantId: 'house',
    kind: 'winback',
    locale: 'en',
    headline: '',
    // The house look as migration 0098's `moment-house` campaign has it;
    // the app draws only the gradient and the countdown manners from it.
    look: {
      accentLight: '#1f6f4a',
      accentDark: '#7fd3a6',
      gradient: 'house',
      motion: 'none',
      countdownStyle: 'auto',
      liveSecondsFromHours: 24,
    },
    images: [],
    surfaces: {
      fullscreen: false,
      todayBanner: { on: true, snoozeDays: MOMENT_SNOOZE_DAYS, returnLastDay: true },
      offerSheet: true,
      planPageHeader: false,
      afterMilestone: false,
      email: { on: false, opening: false, lastDay: false },
      push: { on: false, which: 'lastDay' },
      bell: false,
    },
  };
}

/** The notes once a banner came back for its last day. */
export function noteBannerReturned(notes: StoredOfferNotes, creative: Creative): StoredOfferNotes {
  const returned = notes.bannerReturned ?? [];
  return returned.includes(creative.campaignId)
    ? notes
    : { ...notes, bannerReturned: [...returned, creative.campaignId] };
}

/** The notes once a campaign opened full screen. */
export function noteFullscreen(notes: StoredOfferNotes, creative: Creative, now: Date): StoredOfferNotes {
  const shown = notes.fullscreenShown ?? [];
  return {
    ...notes,
    fullscreenShown: shown.includes(creative.campaignId) ? shown : [...shown, creative.campaignId],
    fullscreenAt: now.toISOString(),
  };
}

/** The values a campaign's words may name, from data. */
export interface CopyValues {
  firstPeriodPrice?: string | undefined;
  renewalPrice?: string | undefined;
  closesDate?: string | undefined;
  closesTime?: string | undefined;
  daysLeft?: string | undefined;
  word1?: string | undefined;
  lexQuestions?: string | undefined;
  wordsKept?: string | undefined;
  name?: string | undefined;
}

/**
 * The values a priced campaign's words may name for this offer (F5): its
 * two prices in the seller's words, and its own latest end, said the way
 * the night card says it.
 */
export function offerCopyValues(
  offer: Offer | undefined,
  words: { first: string; renewal: string } | undefined,
  now: Date,
): CopyValues {
  if (offer === undefined) return {};
  const end = new Date(offer.closesAt);
  const left = end.getTime() - now.getTime();
  const open = !Number.isNaN(left) && left > 0;
  return {
    firstPeriodPrice: words?.first,
    renewalPrice: words?.renewal,
    closesDate: open ? closingDate(end, now) : undefined,
    closesTime: open ? closingTime(end) : undefined,
    daysLeft: open ? String(Math.ceil(left / DAY)) : undefined,
  };
}

/**
 * A campaign's words with its placeholders filled from data, or undefined
 * when one cannot be filled (an unknown name, or a value that is not
 * there): a sentence with a hole in it is worse than the house words,
 * which the caller then uses.
 */
export function fillCopy(text: string | undefined, values: CopyValues): string | undefined {
  if (text === undefined || text.trim() === '') return undefined;
  const names = [...text.matchAll(/\{(\w+)\}/g)].map((match) => match[1] ?? '');
  const known = values as Record<string, string | undefined>;
  if (names.some((name) => known[name] === undefined || known[name] === '')) return undefined;
  return text.replace(/\{(\w+)\}/g, (_, name: string) => known[name] ?? '');
}
