import { useEffect, useState } from 'react';
import { t } from '@/i18n/index.js';
import styles from '@/features/everywhere/NudgeCard.module.css';
import { SmallArt } from './art/Seal.js';
import own from './AfterMilestoneCard.module.css';
import { milestoneWords, type MomentMilestone } from './moment.js';
import { noteSellingShown } from './sellingSignals.js';
import { Upgrade } from './Upgrade.js';

/**
 * The card on the next visit to Today after a milestone (moment offer §5
 * M6): the win said back, what Pro would add, "See Pro" and "Not now".
 * Never in the celebration itself, at most one a month, once per kind of
 * milestone. No price and no countdown here: "See Pro" opens the offer
 * sheet, and it is there, at that moment, that the server may give the
 * learner the moment offer.
 */
export function MomentMilestoneCard({
  milestone,
  count,
  onNotNow,
}: {
  milestone: MomentMilestone;
  count: number | undefined;
  onNotNow: () => void;
}): React.JSX.Element {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    noteSellingShown();
  }, []);
  const words = milestoneWords(milestone, count);
  return (
    <aside className={styles.card} aria-labelledby="moment-milestone">
      <div className={styles.head}>
        <span className={own.art} aria-hidden="true">
          <SmallArt />
        </span>
        <span className={styles.text}>
          <h2 id="moment-milestone" className={styles.title}>
            {words.title}
          </h2>
          <p className={styles.line}>{words.line}</p>
        </span>
      </div>
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.primary}
          onClick={() => {
            setOpen(true);
          }}
        >
          {t('moment.milestone.see')}
        </button>
        <button type="button" className={styles.quiet} onClick={onNotNow}>
          {t('nudge.notNow')}
        </button>
      </div>
      {open && (
        <Upgrade
          occasion="settings"
          moment="milestone_card"
          onClose={() => {
            setOpen(false);
          }}
        />
      )}
    </aside>
  );
}
