import type { ApiNudgeId } from '@/api/types.js';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { t, type MessageKey } from '@/i18n/index.js';
import type { CardGroup, CardLink, CardTile } from './getapp.js';
import { BROWSER_LOGOS, PLAY_QR, STORE_BADGES } from './stores.js';

import styles from './NudgeCard.module.css';

/** What the card's main button does, on a card without store badges. */
export type NudgeAction =
  { kind: 'link'; href: string; label: MessageKey } | { kind: 'button'; label: MessageKey; run: () => void };

/** The card's words: by its id, or given (the app cards say what this device gets). */
export interface NudgeWords {
  title: MessageKey;
  line: MessageKey;
}

const ICONS: Record<ApiNudgeId, IconName> = {
  extension: 'grid',
  desktop_safari: 'grid',
  desktop_power: 'grid',
  on_your_computer: 'grid',
  on_your_phone: 'cards',
  android_browser: 'cards',
  connector: 'sparkles',
  kindle: 'notebook',
};

/** The Lexpad app icon the stores show (public/icons), with the platforms' rounded corners. */
const LEXPAD_ICON = '/icons/icon-192.png';

/** Apple's minimum height for its badge; the other phone badges match it. */
const BADGE = 40;
/** The browsers' white store tiles, shown alone (see `StoreBadge.tall`). */
const TALL_BADGE = 48;

/** The Apple mark, as the site draws it on its Mac download buttons (landing marks-v1.svg#apple). */
function AppleMark(): React.JSX.Element {
  return (
    <svg className={styles.appleMark} viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
      <path
        fill="currentColor"
        d="M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.039 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.701"
      />
    </svg>
  );
}

function Tile({ id, tile }: { id: ApiNudgeId; tile: CardTile | undefined }): React.JSX.Element {
  if (tile?.kind === 'lexpad')
    return <img className={styles.appIcon} src={LEXPAD_ICON} alt="" width={44} height={44} />;
  if (tile?.kind === 'browser')
    return (
      <span className={styles.logoTile} aria-hidden="true">
        <img src={BROWSER_LOGOS[tile.browser]} alt="" width={26} height={26} />
      </span>
    );
  return (
    <span className={styles.icon} aria-hidden="true">
      <Icon name={ICONS[id]} size={20} weight={1.9} />
    </span>
  );
}

/** One way to get it: the store's own badge, unmodified, or the Mac app's download button. */
function LinkOut({ link, onAct }: { link: CardLink; onAct: () => void }): React.JSX.Element {
  if (link.kind === 'mac')
    return (
      <a
        className={styles.download}
        href={link.href}
        target="_blank"
        rel="noopener noreferrer"
        onClick={onAct}
      >
        <AppleMark />
        {t('getapp.downloadMac')}
      </a>
    );
  const badge = STORE_BADGES[link.store];
  const shown = badge.tall === true ? TALL_BADGE : BADGE;
  const width = Math.round((badge.width / badge.height) * shown);
  return (
    <a
      className={badge.tall === true ? `${styles.badge} ${styles.tall}` : styles.badge}
      href={link.href}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={t(badge.alt)}
      onClick={onAct}
    >
      <img
        className={badge.srcOnDark === undefined ? undefined : styles.onLight}
        src={badge.src}
        alt=""
        width={width}
        height={shown}
      />
      {badge.srcOnDark !== undefined && (
        <img className={styles.onDark} src={badge.srcOnDark} alt="" width={width} height={shown} />
      )}
    </a>
  );
}

/**
 * One card on Today that suggests another surface: what it is for, the way
 * to get it on this device, a close button and "Not now" (both put it away
 * for the server's `snoozeDays`), and "Don't show again". No modal and no
 * countdown; it sits in the page like any other card.
 *
 * A card that offers an app or the extension shows the stores' own badges
 * (`groups`); the others have one button (`action`).
 */
export function NudgeCard({
  id,
  words,
  tile,
  groups,
  action,
  note,
  onAct,
  onNotNow,
  onNever,
}: {
  id: ApiNudgeId;
  /** The card's words; by default `nudge.<id>.title` and `.line`. */
  words?: NudgeWords | undefined;
  tile?: CardTile | undefined;
  /** The stores' badges, in groups ("On your phone", "On this Mac"). */
  groups?: readonly CardGroup[] | undefined;
  /** The one button, on a card without badges. */
  action?: NudgeAction | undefined;
  /** A line under the buttons, such as "Link copied". */
  note?: string | undefined;
  onAct: () => void;
  onNotNow: () => void;
  onNever: () => void;
}): React.JSX.Element {
  const titleId = `nudge-${id}`;
  const title = words?.title ?? (`nudge.${id}.title` as MessageKey);
  const line = words?.line ?? (`nudge.${id}.line` as MessageKey);
  return (
    <aside className={styles.card} aria-labelledby={titleId}>
      <div className={styles.head}>
        <Tile id={id} tile={tile} />
        <span className={styles.text}>
          <h2 id={titleId} className={styles.title}>
            {t(title)}
          </h2>
          <p className={styles.line}>{t(line)}</p>
        </span>
        <button
          type="button"
          className={styles.close}
          aria-label={t('nudge.close')}
          title={t('nudge.notNow')}
          onClick={onNotNow}
        >
          <Icon name="close" size={16} weight={2} />
        </button>
      </div>
      {groups !== undefined && groups.length > 0 && (
        <div className={styles.groups}>
          <div className={styles.groupList}>
            {groups.map((group, index) => (
              <div
                key={index}
                className={styles.group}
                role={group.label === undefined ? undefined : 'group'}
                aria-label={group.label === undefined ? undefined : t(group.label)}
              >
                {group.label !== undefined && <p className={styles.groupLabel}>{t(group.label)}</p>}
                {group.hint !== undefined && <p className={styles.groupHint}>{t(group.hint)}</p>}
                <div className={styles.links}>
                  {group.links.map((link) => (
                    <LinkOut key={link.href} link={link} onAct={onAct} />
                  ))}
                </div>
                {group.qr === true && (
                  <div className={styles.scan}>
                    <img className={styles.qr} src={PLAY_QR} alt={t('getapp.qrAlt')} width={88} height={88} />
                    <p className={styles.scanLine}>{t('getapp.scanLine')}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
      <div className={styles.actions}>
        {action?.kind === 'link' && (
          <a
            className={styles.primary}
            href={action.href}
            target="_blank"
            rel="noopener noreferrer"
            onClick={onAct}
          >
            {t(action.label)}
          </a>
        )}
        {action?.kind === 'button' && (
          <button
            type="button"
            className={styles.primary}
            onClick={() => {
              onAct();
              action.run();
            }}
          >
            {t(action.label)}
          </button>
        )}
        <button type="button" className={styles.quiet} onClick={onNotNow}>
          {t('nudge.notNow')}
        </button>
        <button type="button" className={styles.quiet} onClick={onNever}>
          {t('nudge.never')}
        </button>
      </div>
      {note !== undefined && (
        <p className={styles.note} role="status">
          {note}
        </p>
      )}
    </aside>
  );
}
