import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { getMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { InboxSheet } from './InboxSheet.js';
import { refreshInbox } from './inbox.js';
import { cx } from '@/lib/cx.js';
import styles from './Bell.module.css';

/**
 * The bell on Today, beside the streak: the quiet place where announcements,
 * gifts and come-back notes live, whether or not a pop-up ever showed them.
 *
 * It draws from the local copy at once and asks the server for the newest
 * page when Today opens and whenever the app comes back to the foreground.
 * The dot means there is something unread; it carries no number, because a
 * count on a bell is a small demand for attention and this app makes none.
 */
/** How long the bell swings for; matches bellRing's duration in motion.css. */
const RING_MS = 700;

export function Bell(): React.JSX.Element {
  const navigate = useNavigate();
  const inbox = useLiveQuery(() => getMeta('inbox'), null, []);
  const [open, setOpen] = useState(false);
  // Whether the last read reached the server; undefined while it is under way.
  const [reached, setReached] = useState<boolean | undefined>();

  useEffect(() => {
    let live = true;
    const refresh = (): void => {
      void refreshInbox().then((ok) => {
        if (live) setReached(ok);
      });
    };
    refresh();
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') refresh();
    };
    document.addEventListener('visibilitychange', onVisible);
    const offResume = platform.lifecycle.onResume(refresh);
    const offPush = platform.push.onReceive(refresh);
    return () => {
      live = false;
      document.removeEventListener('visibilitychange', onVisible);
      offResume();
      offPush();
    };
  }, []);

  const unread = (inbox?.unread ?? 0) > 0;
  // Ring once when the unread count goes up: a message has just arrived, or
  // arrived since Today was last on screen. Never on a count that went down.
  const unreadCount = inbox?.unread ?? 0;
  const seen = useRef<number | undefined>(undefined);
  const [ringing, setRinging] = useState(false);
  useEffect(() => {
    const before = seen.current;
    seen.current = unreadCount;
    if (before === undefined || unreadCount <= before) return;
    setRinging(true);
    const stop = window.setTimeout(() => {
      setRinging(false);
    }, RING_MS);
    return () => {
      window.clearTimeout(stop);
    };
  }, [unreadCount]);

  return (
    <>
      <button
        type="button"
        className={cx(styles.bell, unread && styles.unread, ringing && styles.ringing)}
        aria-label={unread ? t('inbox.bellUnread') : t('inbox.bell')}
        aria-haspopup="dialog"
        onClick={() => {
          setOpen(true);
          void refreshInbox().then(setReached);
        }}
      >
        <span className={styles.face}>
          <span className={styles.icon}>
            <Icon name="bell" size={19} weight={1.9} />
          </span>
        </span>
        {unread && <span className={styles.dot} aria-hidden="true" />}
      </button>
      {open && (
        <InboxSheet
          items={inbox?.notifications}
          failed={reached === false}
          onClose={() => {
            setOpen(false);
          }}
          onOpen={(path) => {
            setOpen(false);
            void navigate(path);
          }}
        />
      )}
    </>
  );
}
