/**
 * Today's side of a campaign (offer presentation spec §3): whether the
 * banner takes the card place, whether the full-screen offer opens on this
 * first visit of the run, and the writes that keep their caps. The rules
 * are `features/billing/campaign.ts`; this gathers what they need.
 */
import { useEffect, useState } from 'react';
import type { ApiBillingState } from '@/api/types.js';
import { db, getMeta, setMeta, type StoredCelebrate, type StoredOfferNotes } from '@/db/schema.js';
import { useAuth } from '@/features/auth/session.js';
import {
  afterMilestoneShows,
  noteAfterMilestone,
  bannerShows,
  fullscreenShows,
  noteBannerReturned,
  noteBannerDay,
  noteFullscreen,
  pushedCampaign,
  snoozeBanner,
  type CampaignPick,
} from '@/features/billing/campaign.js';
import { openOffer, paidPlan } from '@/features/billing/offer.js';
import {
  freshMilestone,
  isMomentOffer,
  momentMilestoneShows,
  noteMomentMilestone,
  type MomentMilestone,
} from '@/features/billing/moment.js';
import { onIOS } from '@/features/billing/play.js';
import { canBuyHere, freeNotebook, useBilling } from '@/features/billing/state.js';
import { runningTrial } from '@/features/billing/trial.js';
import { serverNow } from '@/lib/serverClock.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';

/** Whether the full-screen offer had its one chance in this run of the app. */
let fullscreenTried = false;
/** It opened in this run: that was the run's plan touch, so no banner follows it. */
let fullscreenOpenedThisRun = false;

/**
 * The campaign a card was put on screen for in this run: it stays (back from
 * a word, a session) until it is answered, even though putting it on screen
 * wrote the note that would otherwise end its rule (once per campaign, a
 * last-day return).
 */
let bannerHeld: string | undefined;
/**
 * A trial card or a celebration was on screen in this run: it was the run's
 * one plan touch, so no campaign surface follows it later in the run (not
 * even after its "Not now").
 */
let touchTaken = false;
let afterMilestoneHeld: string | undefined;
/** The moment card after a milestone was put on screen in this run (by its kind). */
let momentMilestoneHeld: string | undefined;

/** For tests: a new run of the app. */
export function forgetCampaignRun(): void {
  fullscreenTried = false;
  fullscreenOpenedThisRun = false;
  bannerHeld = undefined;
  afterMilestoneHeld = undefined;
  momentMilestoneHeld = undefined;
  touchTaken = false;
}

async function writeNotes(change: (notes: StoredOfferNotes) => StoredOfferNotes): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    await setMeta('offerNotes', change(await getMeta('offerNotes')));
  });
}

export interface TodayCampaign {
  /** What decides it has been read here (local reads only). */
  settled: boolean;
  pick: CampaignPick | undefined;
  banner: boolean;
  /** The full-screen offer should open now (once per run, first visit). */
  fullscreen: boolean;
  /** The banner was put on screen (a last-day return is spent by it). */
  bannerShown: () => void;
  /** The after-milestone card takes the card place this visit. */
  afterMilestone: boolean;
  /** It was put on screen: once per campaign, and the run's plan touch. */
  afterMilestoneShown: () => void;
  /** "Not now" on it: gone, and not back (it was once per campaign). */
  afterMilestoneNotNow: () => void;
  /**
   * The moment offer's card after a milestone (billing/moment.ts, §5 M6):
   * the milestone it speaks of, when it takes the card place this visit.
   */
  momentMilestone: { id: MomentMilestone; count: number | undefined } | undefined;
  /** It was put on screen: once per kind, one a month, the run's plan touch. */
  momentMilestoneShown: () => void;
  /** "Not now" on it: gone for this run (it was already spent). */
  momentMilestoneNotNow: () => void;
  notNow: () => void;
  /** "Don't remind me": the account's switch, and the banner goes for good here. */
  stop: () => Promise<void>;
  fullscreenOpened: () => void;
}

export function useTodayCampaign({
  notebook,
  celebrate,
  today,
  planAtStart,
  quiet,
  kept,
}: {
  notebook: { targetLang: string; meaningLang: string } | undefined | null;
  celebrate: StoredCelebrate | null;
  today: number;
  planAtStart: boolean;
  /** A celebration or the trial owns this visit: no campaign surface competes. */
  quiet: boolean;
  /** The account's last plan kept on this device, for a cold start (offers past their close are dropped). */
  kept?: ApiBillingState | undefined;
}): TodayCampaign {
  const live = useBilling((s) => s.state);
  const state = live ?? kept ?? null;
  const setReminders = useBilling((s) => s.setReminders);
  const createdAt = useAuth((s) => s.user?.createdAt);
  const notes = useLiveQuery<StoredOfferNotes | null>(async () => getMeta('offerNotes'), null, []);
  const [now] = useState(() => new Date(serverNow()));
  const [firstVisit] = useState(() => !fullscreenTried);

  const offer = openOffer(state, now);
  const sells =
    canBuyHere(state) &&
    !paidPlan(state) &&
    notebook !== null &&
    !freeNotebook(state, notebook?.targetLang, notebook?.meaningLang);
  const signals = {
    now,
    createdAt: createdAt === undefined ? undefined : new Date(createdAt),
    notes: notes ?? {},
    sells,
    inTrial: runningTrial(state, now) !== undefined,
    bigToday: celebrate?.spent.includes(`big:${String(today)}`) === true,
  };
  const ready =
    notes !== null &&
    notebook !== null &&
    (planAtStart || (live === null && kept !== undefined)) &&
    !quiet &&
    !touchTaken;
  useEffect(() => {
    if (quiet) touchTaken = true;
  }, [quiet]);
  const pick = ready ? pushedCampaign(state, offer, signals) : undefined;
  // Full screen only from the server's own answer in hand as the visit
  // began, never from the kept copy: the run's one chance is not spent on
  // a plan that may be out of date.
  const readyLive = ready && planAtStart && live !== null;
  const fullscreen = readyLive && firstVisit && fullscreenShows(pick, signals);
  const id = pick?.creative.campaignId;
  const banner =
    ready &&
    !fullscreen &&
    id !== undefined &&
    (bannerHeld === id ||
      (!fullscreenOpenedThisRun && afterMilestoneHeld === undefined && bannerShows(pick, signals)));
  // After a milestone, the next visit: below the banner in priority, the
  // run's one plan touch like the others.
  const afterMilestone =
    ready &&
    !fullscreen &&
    !banner &&
    id !== undefined &&
    (afterMilestoneHeld === id ||
      (!fullscreenOpenedThisRun && bannerHeld === undefined && afterMilestoneShows(pick, signals)));
  // The moment offer's card after a milestone: below the campaign's own
  // surfaces, the run's one plan touch like them (moment offer §5 M6).
  const fresh = notes === null ? undefined : freshMilestone(notes, now);
  const momentMilestone =
    ready &&
    !fullscreen &&
    !banner &&
    !afterMilestone &&
    fresh !== undefined &&
    (momentMilestoneHeld === fresh.key ||
      (!fullscreenOpenedThisRun &&
        bannerHeld === undefined &&
        afterMilestoneHeld === undefined &&
        momentMilestoneShows(state, {
          now,
          createdAt: signals.createdAt,
          notes,
          sells,
          ios: onIOS(),
          offer,
        })))
      ? { id: fresh.id, count: fresh.count }
      : undefined;
  // The full-screen offer has one chance a run: the first visit to Today.
  useEffect(() => {
    if (readyLive) fullscreenTried = true;
  }, [readyLive]);

  return {
    settled: notes !== null,
    pick,
    afterMilestone,
    afterMilestoneNotNow: () => {
      afterMilestoneHeld = undefined;
    },
    afterMilestoneShown: () => {
      fullscreenTried = true;
      const creative = pick?.creative;
      if (creative === undefined) return;
      afterMilestoneHeld = creative.campaignId;
      void writeNotes((current) => noteAfterMilestone(current, creative));
    },
    momentMilestone,
    momentMilestoneShown: () => {
      fullscreenTried = true;
      if (fresh === undefined) return;
      momentMilestoneHeld = fresh.key;
      void writeNotes((current) => noteMomentMilestone(current, new Date(serverNow())));
    },
    momentMilestoneNotNow: () => {
      momentMilestoneHeld = undefined;
    },
    banner,
    fullscreen,
    bannerShown: () => {
      // The banner was this run's plan touch: no full screen after it.
      fullscreenTried = true;
      const creative = pick?.creative;
      if (creative === undefined) return;
      bannerHeld = creative.campaignId;
      // A moment offer's banner shows on one day's visits only (§5 M7).
      if (isMomentOffer(pick?.offer)) {
        void writeNotes((current) => noteBannerDay(current, creative, new Date(serverNow())));
      }
      const snoozed = notes?.bannerSnoozedUntil?.[creative.campaignId];
      if (snoozed !== undefined && Date.parse(snoozed) > Date.now()) {
        void writeNotes((current) => noteBannerReturned(current, creative));
      }
    },
    notNow: () => {
      bannerHeld = undefined;
      const creative = pick?.creative;
      if (creative === undefined) return;
      void writeNotes((current) => snoozeBanner(current, creative, new Date(serverNow())));
    },
    stop: async () => {
      bannerHeld = undefined;
      afterMilestoneHeld = undefined;
      const creative = pick?.creative;
      await setReminders(false);
      if (creative !== undefined) {
        await writeNotes((current) => ({
          ...current,
          bannerDone: [...(current.bannerDone ?? []), creative.campaignId],
        }));
      }
    },
    fullscreenOpened: () => {
      fullscreenTried = true;
      fullscreenOpenedThisRun = true;
      const creative = pick?.creative;
      if (creative === undefined) return;
      void writeNotes((current) => noteFullscreen(current, creative, new Date(serverNow())));
      // It takes the day's one big moment (BIG_PER_DAY).
      void import('@/features/celebrate/state.js')
        .then((moment) => moment.noteBigMoment())
        .catch(() => undefined);
    },
  };
}
