import { useEffect, useState } from 'react';
import { db, getMeta } from '@/db/schema.js';
import { countAccountWords } from '@/features/celebrate/state.js';
import { localDay } from '@/features/celebrate/view.js';
import { invitesInThisApp } from './where.js';
import { inviteOffered, noteWordsMoment, wordsMomentReached } from './state.js';

/**
 * Whether Today shows the invitation card in this visit, and the days it
 * promises. Decided once, from the stored state, when Today opens: the card
 * marks itself shown as soon as it is on screen, and must not then vanish
 * under the reader. Put away, it is gone until the next good moment a month
 * on. Opening Today is also where the words moment is noticed (it never
 * offers the card the same day it is noted).
 */
export function useInviteOffer(): { days: number | undefined; dismiss: () => void } {
  const [days, setDays] = useState<number | undefined>(undefined);
  useEffect(() => {
    // Never in the iPhone app (where.ts).
    if (!invitesInThisApp()) return;
    const run = { live: true };
    void (async () => {
      const today = localDay();
      const state = await getMeta('invite');
      if (state?.wordsMoment !== true) {
        const [words, practiced] = await Promise.all([
          countAccountWords(),
          db.dayStats.filter((stat) => stat.reviewed > 0).count(),
        ]);
        if (wordsMomentReached(words, practiced)) await noteWordsMoment(today);
      }
      if (!run.live || !inviteOffered(state, today, Date.now())) return;
      setDays(state?.view?.days);
    })().catch(() => undefined);
    return () => {
      run.live = false;
    };
  }, []);
  return {
    days,
    dismiss: () => {
      setDays(undefined);
    },
  };
}
