/**
 * Whether Today's "Confirm your e-mail" row wants to show, and the numbers it
 * states: apart from the row (VerifyBanner.tsx) so Today can decide its one
 * notice (features/today/TodayNotice.tsx) without drawing the row.
 */
import { useEffect, useState } from 'react';
import { getMeta } from '@/db/schema.js';
import { useConfig } from '@/lib/useConfig.js';
import { recallRead, rememberRead } from '@/lib/readMemory.js';
import { useAuth } from './session.js';

/** How long a dismissed banner stays away: until about this time tomorrow. */
export const SNOOZE_MS = 24 * 60 * 60 * 1000;

/** Where the last read of the snooze is remembered for this run. */
export const SNOOZE_READ = 'verifySnooze';

/**
 * The AI cards an account may have before its address is confirmed, in
 * total, for a server that predates `GET /config` `limits` (lexpad_back
 * 23ebc28): a named copy of the flag `ai_unverified_card_limit`, as the
 * public site's `LIMITS['unconfirmed_cards']` (landing `scripts/features.py`)
 * is. Once the server sends `limits`, its number is the one shown.
 */
export const UNCONFIRMED_AI_CARDS = 10;

/**
 * The number the e-mail row states: the server's (`limits.aiCardsUnconfirmed`),
 * else the named copy above for an older server, or null when the server
 * says there is no such gate (then the row states no number).
 */
export function useUnconfirmedCards(): number | null {
  const cards = useConfig((state) => state.unconfirmedCards);
  const ensure = useConfig((state) => state.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);
  return cards === undefined ? UNCONFIRMED_AI_CARDS : cards;
}

/** Hidden while the snooze is unknown (undefined) or still running. */
function isSnoozed(until: number | null | undefined): boolean {
  return until === undefined || (until !== null && until > Date.now());
}

/**
 * Whether the row wants to be on Today: an unconfirmed address that was not
 * put away for the day. Undefined while the snooze is still being read; on a
 * return to Today the last answer is drawn at once (lib/readMemory.ts), so
 * Today decides its one notice without anything flashing or arriving late.
 */
export function useVerifyWanted(): boolean | undefined {
  const user = useAuth((state) => state.user);
  const [snooze, setSnooze] = useState<number | null | undefined>(
    () => recallRead(SNOOZE_READ) as number | null | undefined,
  );
  useEffect(() => {
    let alive = true;
    void getMeta('verifySnoozedUntil').then((until) => {
      rememberRead(SNOOZE_READ, until);
      if (alive) setSnooze(until);
    });
    return () => {
      alive = false;
    };
  }, []);
  if (user === null || user.emailVerified) return false;
  if (snooze === undefined) return undefined;
  return !isSnoozed(snooze);
}
