/**
 * What a card that offers an app says and links to, on this device: "get
 * the right app for this device" (owner, 2026-10-17). Pure, so each device
 * has a test; `NudgeCard` only draws it.
 *
 * - A phone's browser: that phone's own store (N6). Google Play on Android;
 *   the App Store on an iPhone or iPad once `releases.ios` is live.
 * - A computer's browser: the phone apps' badges, and the desktop app for
 *   this computer (N5); the Mac app first in Safari on a Mac (N2), where no
 *   extension can be installed.
 * - Chrome, Edge or Firefox on a computer: the extension's listing in this
 *   browser's own store (N1). Never at the same time as the apps: Today has
 *   one card a session.
 *
 * Every link carries the card's `ref` (N1–N8), so the site's and the
 * stores' own counts can tell a visit from the card apart.
 */
import type { ApiNudgeId, ApiSurfaceStatus } from '@/api/types.js';
import type { MessageKey } from '@/i18n/index.js';
import { extensionStore, type Device } from '@/lib/platform/device.js';
import { appOffer, computerCardOffer, type DesktopOs, type PhoneStore } from './apps.js';
import {
  APP_STORE_URL,
  EXTENSION_STORES,
  MAC_DOWNLOAD_URL,
  MICROSOFT_STORE_URL,
  NUDGE_REF,
  PLAY_URL,
  withRef,
} from './links.js';
import type { StoreId } from './stores.js';

/** The square at the card's start: Lexpad's own icon, or the browser's logo. */
export type CardTile = { kind: 'lexpad' } | { kind: 'browser'; browser: 'chrome' | 'edge' | 'firefox' };

/** One way to get it: a store's own badge, or the Mac app's download page. */
export type CardLink = { kind: 'badge'; store: StoreId; href: string } | { kind: 'mac'; href: string };

/** Links that belong together, under an optional heading ("On your phone"). */
export interface CardGroup {
  label?: MessageKey | undefined;
  /** One line under the heading. */
  hint?: MessageKey | undefined;
  links: CardLink[];
  /**
   * A QR code that opens the Google Play listing on a phone, shown beside
   * the badge on a computer's wide screen: a click on the badge there
   * installs from the Play website, and the phone then holds an app nobody
   * opens (marketing/aso/2026-10-24-play-listing.md).
   */
  qr?: boolean | undefined;
}

export interface GetAppContent {
  title: MessageKey;
  line: MessageKey;
  tile: CardTile;
  groups: CardGroup[];
}

/** The cards drawn with store badges rather than a button. */
export type GetAppId = Extract<
  ApiNudgeId,
  'extension' | 'desktop_safari' | 'on_your_phone' | 'android_browser'
>;

export function isGetAppId(id: ApiNudgeId): id is GetAppId {
  return id === 'extension' || id === 'desktop_safari' || id === 'on_your_phone' || id === 'android_browser';
}

const PHONE_HREF: Record<PhoneStore, string> = { play: PLAY_URL, appStore: APP_STORE_URL };

/** The phone group a computer's card shows: the badges, and the QR code when Play is one of them. */
function phoneGroup(stores: readonly PhoneStore[], ref: string, label?: MessageKey): CardGroup {
  return { label, links: phoneLinks(stores, ref), qr: stores.includes('play') };
}

function phoneLinks(stores: readonly PhoneStore[], ref: string): CardLink[] {
  return stores.map((store) => ({ kind: 'badge', store, href: withRef(PHONE_HREF[store], ref) }));
}

function desktopLink(os: DesktopOs, ref: string): CardLink {
  return os === 'mac'
    ? { kind: 'mac', href: withRef(MAC_DOWNLOAD_URL, ref) }
    : { kind: 'badge', store: 'microsoftStore', href: withRef(MICROSOFT_STORE_URL, ref) };
}

function desktopGroup(os: DesktopOs, ref: string, labelled: boolean): CardGroup {
  return {
    label: labelled ? (os === 'mac' ? 'getapp.onThisMac' : 'getapp.onThisPc') : undefined,
    hint: labelled ? (os === 'mac' ? 'getapp.desktopHintMac' : 'getapp.desktopHintPc') : undefined,
    links: [desktopLink(os, ref)],
  };
}

/**
 * The card's words and links, or undefined when this device has nothing it
 * could use (the rules in `rules.ts` already make that rare: a trigger is
 * only true when there is something to offer).
 */
export function getAppContent(
  id: GetAppId,
  device: Device,
  surfaces: readonly ApiSurfaceStatus[],
): GetAppContent | undefined {
  const ref = NUDGE_REF[id];
  const offer = appOffer(device, surfaces);
  switch (id) {
    case 'extension': {
      const store = extensionStore(device);
      if (store === undefined) return undefined;
      return {
        title: 'nudge.extension.title',
        line: 'nudge.extension.line',
        tile: { kind: 'browser', browser: store },
        groups: [{ links: [{ kind: 'badge', store, href: withRef(EXTENSION_STORES[store], ref) }] }],
      };
    }
    case 'android_browser': {
      if (offer.phones.length === 0) return undefined;
      return {
        title: 'nudge.android_browser.title',
        line: 'nudge.android_browser.line',
        tile: { kind: 'lexpad' },
        groups: [{ links: phoneLinks(offer.phones, ref) }],
      };
    }
    case 'on_your_phone': {
      const desktop = computerCardOffer(device, surfaces).desktop;
      if (offer.phones.length === 0) {
        if (desktop === undefined) return undefined;
        // Only the computer's app is left to offer: a card about it alone.
        return {
          title: desktop === 'mac' ? 'getapp.desktopOnlyMac.title' : 'getapp.desktopOnlyPc.title',
          line: desktop === 'mac' ? 'getapp.desktopHintMac' : 'getapp.desktopHintPc',
          tile: { kind: 'lexpad' },
          groups: [desktopGroup(desktop, ref, false)],
        };
      }
      const groups: CardGroup[] = [
        phoneGroup(offer.phones, ref, desktop === undefined ? undefined : 'getapp.onYourPhone'),
      ];
      if (desktop !== undefined) groups.push(desktopGroup(desktop, ref, true));
      return {
        title: 'nudge.on_your_phone.title',
        line: 'nudge.on_your_phone.line',
        tile: { kind: 'lexpad' },
        groups,
      };
    }
    case 'desktop_safari': {
      if (offer.desktop !== 'mac') return undefined;
      const groups: CardGroup[] = [{ links: [desktopLink('mac', ref)] }];
      if (offer.phones.length > 0) groups.push(phoneGroup(offer.phones, ref, 'getapp.onYourPhone'));
      return {
        title: 'nudge.desktop_safari.title',
        line: 'nudge.desktop_safari.line',
        tile: { kind: 'lexpad' },
        groups,
      };
    }
  }
}
