import { useEffect, useMemo, useRef, useState } from 'react';
import type { ApiNudgeEvent, ApiNudgeId } from '@/api/types.js';
import { Toast } from '@/components/ui/Toast.js';
import { getMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { currentDevice } from '@/lib/platform/device.js';
import { platform } from '@/lib/platform/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useAuth } from '@/features/auth/session.js';
import { sellingShownThisSession } from '@/features/billing/sellingSignals.js';
import { NudgeCard, type NudgeAction } from '@/features/everywhere/NudgeCard.js';
import { getAppContent, isGetAppId } from '@/features/everywhere/getapp.js';
import { EXTENSION_PAGE_URL, NUDGE_REF, withRef } from '@/features/everywhere/links.js';
import { pickNudge } from '@/features/everywhere/rules.js';
import {
  arrival,
  keepAppSessionAlive,
  loadSignals,
  type LocalSignals,
  recordNudge,
  refreshNudges,
  refreshSurfaces,
  touchAppSession,
} from '@/features/everywhere/state.js';
import { ConnectAssistantSheet } from '@/features/settings/ConnectAssistantSheet.js';
import { loadOffer, shouldOffer } from './offers.js';
import { offersOnToday } from '@/features/reminder/webOffer.js';

/**
 * Everything the choice needs, read from IndexedDB: the server's copy of the
 * rules and history, what the account used, and this device's own signals.
 * Nothing here writes; the writes happen in the effects below.
 */
async function loadSlot() {
  const [nudges, surfaces, snoozed, reminder, webReminder, update] = await Promise.all([
    getMeta('nudges'),
    getMeta('surfaces'),
    getMeta('verifySnoozedUntil'),
    shouldOffer(),
    offersOnToday(),
    loadOffer(),
  ]);
  const base = {
    // The other messages that live in the same place on Today.
    otherMessage: reminder || webReminder || update !== null,
    verifySnoozed: snoozed !== null && snoozed > Date.now(),
  };
  // No copy of the server's rules yet (or the cards are switched off): no
  // card about another surface, though a lead (the trial) may still come.
  if (nudges === null || surfaces === null) return { ...base, nudge: null };
  return { ...base, nudge: { view: nudges.view, surfaces: surfaces.list } };
}

/**
 * What the account did on this device, for the surface cards' triggers: a
 * read of every word, so it is kept apart from the few meta reads above.
 * A lead (the trial's card) is decided without it.
 */
async function loadSlotSignals(): Promise<LocalSignals> {
  return loadSignals(localTimeZone());
}

/**
 * The signals while they are being read. Only ever handed to `pickNudge`
 * when the place is already taken, which it answers before it reads any.
 */
const NO_SIGNALS: LocalSignals = {
  typedWords: 0,
  typedDays: 0,
  words: 0,
  practiceDays: 0,
  practisedToday: false,
  pasteUses: 0,
};

/**
 * A card of Today's own that takes this slot ahead of a surface card: the
 * Pro trial's (`TrialCard`). `pending` while what decides it is still being
 * read (the plan, over the network), so neither a surface card nor the
 * fallback takes the place first and is then pushed out of it.
 */
export interface SlotLead {
  pending: boolean;
  node: React.ReactNode;
}

/**
 * The main button of the cards that have one. The cards that offer an app
 * or the extension show the stores' badges instead (`getAppContent`).
 */
function actionFor(
  id: ApiNudgeId,
  open: { send: (url: string) => void; connect: () => void },
): NudgeAction | undefined {
  const ref = NUDGE_REF[id];
  switch (id) {
    case 'on_your_computer':
      return {
        kind: 'button',
        label: 'nudge.on_your_computer.action',
        run: () => {
          open.send(withRef(EXTENSION_PAGE_URL, ref));
        },
      };
    case 'connector':
      return { kind: 'button', label: 'nudge.connector.action', run: open.connect };
    default:
      return undefined;
  }
}

/**
 * The one place on Today where a card may suggest another surface (the
 * extension, ChatGPT or Claude, and later the apps). It sits below the
 * day's plan and shows at most one card an app session, and none while the
 * reminder offer, an update or the confirm-your-address line is showing:
 * those share this slot. Which card, and whether, is `pickNudge`; what was
 * shown, tapped or put away goes to the server so the caps hold on every
 * device.
 *
 * `fallback` is drawn in the slot while no card is (SRS v2: the one-time
 * Smart invitation), so Today never stacks two suggestions.
 */
export function NudgeSlot({
  fallback,
  lead,
  onSettle,
  quiet = false,
}: {
  fallback?: React.ReactNode;
  lead?: SlotLead | undefined;
  /**
   * Something else has this visit's attention (a celebration on Today):
   * no new surface card starts now. Decided before the place settles, so it
   * never makes a card appear or vanish under the reader.
   */
  quiet?: boolean;
  /**
   * Told whether what this place shows has been decided (local reads only),
   * so Today can draw what sits below it in the same frame: a card that
   * lands after the page below it would push that page down.
   */
  onSettle?: (settled: boolean) => void;
} = {}): React.JSX.Element | null {
  const device = useMemo(() => currentDevice(), []);
  const user = useAuth((state) => state.user);
  const data = useLiveQuery<Awaited<ReturnType<typeof loadSlot>> | undefined>(loadSlot, undefined, []);
  const hasRules = data?.nudge !== null && data?.nudge !== undefined;
  const signals = useLiveQuery<LocalSignals | undefined>(
    async () => (hasRules ? loadSlotSignals() : undefined),
    undefined,
    [hasRules],
  );
  const [session, setSession] = useState<string | undefined>();
  const [closed, setClosed] = useState<string | undefined>();
  const [connecting, setConnecting] = useState(false);
  const [toast, setToast] = useState<string | undefined>();
  const shownFor = useRef<string | undefined>(undefined);

  // Read the server's answers again whenever Today opens or the app comes
  // back, and settle which app session this is.
  useEffect(() => {
    let live = true;
    const start = async (): Promise<void> => {
      void refreshSurfaces().catch(() => undefined);
      // The session first from the copy of the rules already here, so the
      // place is settled from local reads and never waits on the network;
      // then again with what the server says now (the same session, unless
      // its gap changed).
      const before = await getMeta('nudges');
      if (before !== null) {
        const id = await touchAppSession(before.view.rules.sessionGapMinutes);
        if (live) setSession(id);
      }
      await refreshNudges().catch(() => undefined);
      const cached = await getMeta('nudges');
      if (cached === null) return;
      const id = await touchAppSession(cached.view.rules.sessionGapMinutes);
      if (live) setSession(id);
    };
    void start();
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') void start();
      else void keepAppSessionAlive();
    };
    document.addEventListener('visibilitychange', onVisible);
    const offResume = platform.lifecycle.onResume(() => {
      void start();
    });
    return () => {
      live = false;
      document.removeEventListener('visibilitychange', onVisible);
      offResume();
    };
  }, []);

  const verifyShowing = user !== null && !user.emailVerified && data?.verifySnoozed !== true;
  const leadNode = lead === undefined || lead.pending || lead.node === null ? undefined : lead.node;
  const leadWants = lead?.pending === true || leadNode !== undefined;
  const nudge = data?.nudge ?? null;
  // Whether this session's card, if any, is known yet.
  const slotSettled = data !== undefined && (nudge === null || session !== undefined);
  // A surface card waits for the signals; with the place already taken
  // (the lead, a banner) the answer does not depend on them.
  // An offer of Pro already shown in this run of the app counts too: one
  // suggestion at a time, whatever it is about.
  const slotTaken =
    data !== undefined &&
    (data.otherMessage || verifyShowing || leadWants || quiet || sellingShownThisSession());
  const pick =
    nudge === null || data === undefined || session === undefined || (signals === undefined && !slotTaken)
      ? null
      : pickNudge({
          view: nudge.view,
          surfaces: nudge.surfaces,
          device,
          signals: signals ?? NO_SIGNALS,
          arrival: arrival(),
          session,
          // The lead has the place first; a card already shown this session keeps it.
          slotTaken,
          now: new Date(),
        });
  // The lead counts against the same caps as a surface card: never beside a
  // banner that holds the slot, never in a session that already had a card,
  // and not once this week's cards are used up.
  const leadShows =
    leadNode !== undefined &&
    slotSettled &&
    !data.otherMessage &&
    !verifyShowing &&
    pick === null &&
    (nudge === null ||
      (!nudge.view.recentShows.some((show) => show.session === session) &&
        nudge.view.recentShows.length < nudge.view.rules.perWeek));
  // Nothing else takes the place while the lead is still being decided.
  const leadWaiting = lead?.pending === true || (leadNode !== undefined && !slotSettled);
  const decided = slotSettled && lead?.pending !== true;
  useEffect(() => {
    onSettle?.(decided);
  }, [decided, onSettle]);

  const content =
    pick === null || nudge === null || !isGetAppId(pick)
      ? undefined
      : getAppContent(pick, device, nudge.surfaces);
  const action =
    pick === null
      ? undefined
      : actionFor(pick, {
          send: (url) => {
            platform.share
              .link(url, t('everywhere.title'))
              .then((how) => {
                if (how === 'copied') setToast(t('everywhere.linkCopied'));
              })
              .catch(() => undefined);
          },
          connect: () => {
            setConnecting(true);
          },
        });

  // Something to draw for the card picked, on this device.
  const drawable = content !== undefined || action !== undefined;

  // A card on screen is a showing, once per app session.
  useEffect(() => {
    if (pick === null || session === undefined || nudge === null || !drawable) return;
    const key = `${session}:${pick}`;
    if (shownFor.current === key) return;
    shownFor.current = key;
    if (nudge.view.recentShows.some((show) => show.session === session && show.id === pick)) return;
    void recordNudge(pick, 'shown', session).catch(() => undefined);
  }, [pick, session, nudge, drawable]);

  const record = (id: ApiNudgeId, event: ApiNudgeEvent): void => {
    if (session === undefined) return;
    setClosed(`${session}:${id}`);
    // Put away: say where the same thing always is, so nothing is lost.
    if (event === 'not_now' || event === 'never') setToast(t('nudge.putAway'));
    void recordNudge(id, event, session).catch(() => undefined);
  };

  const visible = pick !== null && drawable && closed !== `${session ?? ''}:${pick}`;

  return (
    <>
      {!visible && leadShows && leadNode}
      {!visible && !leadShows && !leadWaiting && fallback}
      {visible && (
        <NudgeCard
          id={pick}
          words={content}
          tile={content?.tile}
          groups={content?.groups}
          action={action}
          onAct={() => {
            record(pick, 'tapped');
          }}
          onNotNow={() => {
            record(pick, 'not_now');
          }}
          onNever={() => {
            record(pick, 'never');
          }}
        />
      )}
      {connecting && (
        <ConnectAssistantSheet
          say={(message) => {
            setToast(message);
          }}
          initial={arrival() === 'claude' ? 'claude' : 'chatgpt'}
          onClose={() => {
            setConnecting(false);
          }}
        />
      )}
      {toast !== undefined && (
        <Toast
          message={toast}
          onDone={() => {
            setToast(undefined);
          }}
        />
      )}
    </>
  );
}
