import { Icon } from '@/components/ui/Icon.js';
import { cx } from '@/lib/cx.js';
import type { MomentCopy } from './copy.js';
import styles from './MomentLine.module.css';

/**
 * A moment as one sentence with its mark (a Line, or a big moment that the
 * day's big one already used): in the summary under the head, or in Today's
 * hero. It fades up once; the mark pops.
 */
export function MomentLine({
  copy,
  tone = 'card',
  className,
}: {
  copy: MomentCopy;
  /** `card` on the summary; `hero` sits inside Today's hero like its other lines. */
  tone?: 'card' | 'hero';
  className?: string | undefined;
}): React.JSX.Element {
  return (
    <p className={cx(styles.line, tone === 'hero' ? styles.hero : styles.card, className)} data-moment="">
      <span className={styles.mark} aria-hidden="true">
        <Icon name={copy.icon === 'boxes' ? 'check' : copy.icon} size={16} weight={2.2} />
      </span>
      <span className={styles.text}>
        {copy.title !== undefined && (
          <>
            <strong className={styles.title}>{copy.title}</strong>{' '}
          </>
        )}
        {copy.line}
      </span>
    </p>
  );
}
