/**
 * Which Lexpad apps this device may be offered: the phone apps' stores and
 * the desktop app. Pure, so every pairing of device and account history has
 * a test.
 *
 * The rules, in the order they are checked:
 *
 * - Only a browser tab is offered an app. The phone apps never point to
 *   another platform (App Store Review Guideline 2.3.10, Google Play's
 *   policies), and the desktop app is already the app.
 * - A store is offered only where its listing can be used: Google Play on an
 *   Android phone or on a computer (Play installs to the learner's phone
 *   from there), the App Store on an iPhone or iPad or on a computer, never
 *   one phone's store on the other phone. The desktop app only on a Mac or
 *   a Windows computer.
 * - Only a surface the server marks `live` (the cross_promotion flag's
 *   `releases`). The iPhone app is built here and stays off until the flag
 *   says `releases.ios: "live"`; nothing in this file names a date.
 * - Never a surface the account has used, on any device. On a computer the
 *   phones count as one: somebody who has either phone app is not asked to
 *   get the other.
 */
import type { ApiSurface, ApiSurfaceStatus } from '@/api/types.js';
import type { Device } from '@/lib/platform/device.js';

export type PhoneStore = 'play' | 'appStore';
export type DesktopOs = 'mac' | 'windows';

export interface AppOffer {
  /** The phone stores to show, Google Play first. */
  phones: PhoneStore[];
  /** The desktop app for this computer, if it may be offered. */
  desktop: DesktopOs | undefined;
}

export const NO_APPS: AppOffer = { phones: [], desktop: undefined };

function status(surfaces: readonly ApiSurfaceStatus[], id: ApiSurface): ApiSurfaceStatus | undefined {
  return surfaces.find((s) => s.surface === id);
}

/** Released and never used by this account: the only surfaces worth offering. */
function offerable(surfaces: readonly ApiSurfaceStatus[], id: ApiSurface): boolean {
  const known = status(surfaces, id);
  return known?.release === 'live' && !known.everUsed;
}

function usedAny(surfaces: readonly ApiSurfaceStatus[], ...ids: ApiSurface[]): boolean {
  return ids.some((id) => status(surfaces, id)?.everUsed === true);
}

/** The apps this device may be offered, given what the server says about the account. */
export function appOffer(device: Device, surfaces: readonly ApiSurfaceStatus[]): AppOffer {
  if (device.shell !== 'web') return NO_APPS;
  if (device.os === 'android')
    return { phones: offerable(surfaces, 'android') ? ['play'] : [], desktop: undefined };
  if (device.os === 'ios')
    return { phones: offerable(surfaces, 'ios') ? ['appStore'] : [], desktop: undefined };
  if (device.mobile) return NO_APPS;

  const phones: PhoneStore[] = [];
  if (!usedAny(surfaces, 'android', 'ios')) {
    if (offerable(surfaces, 'android')) phones.push('play');
    if (offerable(surfaces, 'ios')) phones.push('appStore');
  }
  const desktopOs: DesktopOs | undefined =
    device.os === 'mac' ? 'mac' : device.os === 'windows' ? 'windows' : undefined;
  const desktop = desktopOs !== undefined && offerable(surfaces, 'desktop') ? desktopOs : undefined;
  return { phones, desktop };
}

/** Whether there is anything to offer at all. */
export function offersAnything(offer: AppOffer): boolean {
  return offer.phones.length > 0 || offer.desktop !== undefined;
}

/**
 * What the computer card (N5, "the apps") offers. In Safari on a Mac the
 * Mac app has a card of its own (N2, after typing, since Safari takes no
 * extension), so there N5 keeps to the phones and the Mac app is never
 * offered twice.
 */
export function computerCardOffer(device: Device, surfaces: readonly ApiSurfaceStatus[]): AppOffer {
  const offer = appOffer(device, surfaces);
  if (device.os === 'mac' && device.browser === 'safari') return { ...offer, desktop: undefined };
  return offer;
}
