/** Persian and Arabic meanings need their own face to stay readable. */
function fontFor(lang: LanguageCode): React.CSSProperties | undefined {
  return lang === 'fa' || lang === 'ar' ? { fontFamily: 'var(--fa)' } : undefined;
}

/** "1 day", "3 days", "1 week", "3 weeks": a gap between two returns. */
function gapWords(days: number): string {
  return days >= DAYS_IN_WEEK && days % DAYS_IN_WEEK === 0
    ? t('today.gapWeeks', { count: days / DAYS_IN_WEEK })
    : t('today.gapDays', { count: days });
}

/** Days in a week, for saying a gap of 7 or 21 days as weeks. */
const DAYS_IN_WEEK = 7;

/** A local day as a short date, "Fri, Oct 23", in the app's own date style. */
function shortDate(day: number): string {
  return new Date(`${dayToISODate(day)}T12:00:00Z`).toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  });
}

/**
 * The first visit's hero (M1): the first word is in, when it comes back,
 * and its returns if it is remembered each time, with real dates from the
 * engine (`trailFor`). The last stop is gold when it reaches box 5.
 */
function FirstWin({
  trail,
  word,
  lang,
  words,
  today,
}: {
  trail: readonly TrailStop[];
  word: string;
  /** The notebook's language: the word is set in its own direction and face. */
  lang: LanguageCode;
  words: number;
  today: number;
}): React.JSX.Element {
  const first = trail[0];
  const next =
    first === undefined || first.gap <= 1
      ? t('today.firstNextTomorrow')
      : t('today.firstNextIn', { count: first.gap });
  const [before = '', after = ''] = t('today.firstLine', { word: '\u0000' }).split('\u0000');
  return (
    <>
      <p className={styles.heroHeadline}>
        {words === 1 ? t('today.firstTitle') : t('today.firstTitleMany')}{' '}
        <span className={styles.heroAccent}>{next}</span>
      </p>
      <p className={styles.heroLine}>
        {before}
        <bdi className={styles.heroWord} lang={lang} dir={directionOf(lang)}>
          {word}
        </bdi>
        {after}
      </p>
      <ol className={styles.trail} aria-label={t('today.trailLabel', { word })}>
        {trail.map((stop, index) => (
          <li
            key={stop.day}
            className={cx(styles.stop, index === 0 && styles.stopNext, stop.top && styles.stopTop)}
          >
            <span className={styles.stopDot} aria-hidden="true" />
            <span className={styles.stopWhen}>
              {index === 0
                ? stop.day === today
                  ? t('today.stopToday')
                  : stop.day === today + 1
                    ? t('today.stopTomorrow')
                    : gapWords(stop.gap)
                : gapWords(stop.gap)}
            </span>
            <span className={styles.stopDate}>{shortDate(stop.day)}</span>
          </li>
        ))}
      </ol>
    </>
  );
}

/**
 * A new notebook's few due words (M2): the word that came back by name, why
 * this review matters, and for one word what today's answer does, from the
 * engine (`waitsAfter`).
 */
function Named({
  named,
  due,
  lang,
}: {
  named: NamedDue;
  due: number;
  /** The notebook's language: the word is set in its own direction and face. */
  lang: LanguageCode;
}): React.JSX.Element {
  const word = due === 1 ? named.headwords[0] : undefined;
  const wrong =
    named.waits === undefined
      ? undefined
      : named.waits.wrong <= 0
        ? t('today.namedWrongToday')
        : named.waits.wrong === 1
          ? t('today.namedWrongTomorrow')
          : t('today.namedWrongIn', { count: named.waits.wrong });
  return (
    <>
      <p className={styles.heroHeadline}>
        {word === undefined ? (
          t('today.namedMany', { count: due })
        ) : (
          <WordInLine template={t('today.namedOne', { word: '\u0000' })} word={word} lang={lang} />
        )}{' '}
        <span className={styles.heroAccent}>
          {word === undefined ? t('today.namedAskMany') : t('today.namedAskOne')}
        </span>
      </p>
      <p className={styles.heroLine}>
        {word === undefined ? t('today.namedWhyMany') : t('today.namedWhyOne')}
        {word !== undefined && named.waits !== undefined && (
          <>
            {' '}
            {t('today.namedRight', { count: named.waits.right })} {wrong}
          </>
        )}
      </p>
    </>
  );
}

/**
 * The parts to mark "New" on this visit (parts.ts): decided once, as the
 * visit's own read lands, and held for the visit; then remembered on this
 * device, so each part is marked once.
 */
function useNewParts(on: Record<TodayPart, boolean>, ready: boolean): ReadonlySet<TodayPart> {
  const seen = useLiveQuery<readonly TodayPart[] | null | undefined>(
    () => getMeta('todayParts'),
    undefined,
    [],
  );
  const [held, setHeld] = useState<ReadonlySet<TodayPart> | undefined>(undefined);
  if (held === undefined && ready && seen !== undefined) setHeld(new Set(newParts(on, seen ?? undefined)));
  const key = partsKey(on);
  useEffect(() => {
    if (held === undefined || seen === undefined) return;
    const after = seenAfter(on, seen ?? undefined);
    if (seen !== null && after.length === seen.length) return;
    void setMeta('todayParts', after);
    // `key` stands for `on`, a fresh object every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [held, seen, key]);
  return held ?? NO_PARTS;
}

const NO_PARTS: ReadonlySet<TodayPart> = new Set();

/** Which parts are on, as one string, for an effect's dependencies. */
function partsKey(on: Record<TodayPart, boolean>): string {
  return Object.entries(on)
    .filter(([, value]) => value)
    .map(([part]) => part)
    .join(',');
}

/** The small "New" beside a part that has just appeared on Today, the inbox's own mark. */
function NewMark(): React.JSX.Element {
  return (
    <span className={styles.newMark}>
      <span className={styles.newDot} aria-hidden="true" />
      {t('today.newMark')}
    </span>
  );
}

/**
 * A sentence with the learner's word inside it, the word isolated in its own
 * direction and language, so a Persian or Arabic word in an English sentence
 * never reorders the words around it.
 */
function WordInLine({
  template,
  word,
  lang,
}: {
  /** The sentence with \u0000 where the word goes. */
  template: string;
  word: string;
  lang: LanguageCode;
}): React.JSX.Element {
  const [before = '', after = ''] = template.split('\u0000');
  return (
    <>
      {before}
      <bdi lang={lang} dir={directionOf(lang)}>
        {word}
      </bdi>
      {after}
    </>
  );
}
