import { useEffect, useState } from 'react';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { Skeleton } from '@/components/ui/Skeleton.js';
import type { InboxNotification } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { dirOf } from '@/features/assistant/richText.js';
import { relativeTime } from '@/lib/format.js';
import { useLinkHosts } from '@/lib/useConfig.js';
import { actionView } from './action.js';
import { markInboxRead, unreadIds } from './inbox.js';
import { NotificationAction } from './NotificationAction.js';
import styles from './InboxSheet.module.css';

/**
 * The notifications, newest first.
 *
 * Opening the sheet reads what it shows, so whatever was unread is marked
 * read as it appears; it keeps its "new" mark for as long as the sheet stays
 * open, because the point of the mark is to be seen. Each message is a plain
 * card; one with somewhere to go holds one button (`NotificationAction`):
 * a screen or a form closes the sheet and opens it, checked by the same rule
 * as a tapped pop-up, and a link opens the system browser with the sheet
 * left open. A message with nowhere to go does nothing when tapped.
 */
export function InboxSheet({
  items,
  failed,
  onClose,
  onOpen,
}: {
  /** Undefined until the local copy exists. */
  items: readonly InboxNotification[] | undefined;
  /** The last read did not reach the server. */
  failed: boolean;
  onClose: () => void;
  onOpen: (path: string) => void;
}): React.JSX.Element {
  // Ids that were unread when this sheet showed them. Gathered while
  // rendering, React's way of keeping state in step with a prop, so the mark
  // is there on the very frame the item first appears.
  const [fresh, setFresh] = useState<ReadonlySet<string>>(() => new Set());
  const unseen = items === undefined ? [] : unreadIds(items).filter((id) => !fresh.has(id));
  if (unseen.length > 0) setFresh(new Set([...fresh, ...unseen]));

  // Shown is read. Once marked, the local copy drops them from unreadIds, so
  // this asks once per notification.
  useEffect(() => {
    if (items !== undefined) void markInboxRead(unreadIds(items));
  }, [items]);

  const now = new Date();
  const links = useLinkHosts();

  return (
    <Sheet title={t('inbox.title')} onClose={onClose}>
      {items === undefined && !failed && (
        <div className={styles.loading}>
          <span role="status" className="sr-only">
            {t('inbox.loading')}
          </span>
          <Skeleton lines={3} />
        </div>
      )}
      {items === undefined && failed && (
        <EmptyState
          compact
          tone="quiet"
          icon="bell"
          title={t('inbox.failedTitle')}
          body={t('inbox.failedBody')}
        />
      )}
      {items?.length === 0 && (
        <EmptyState compact icon="bell" title={t('inbox.emptyTitle')} body={t('inbox.emptyBody')} />
      )}
      {items !== undefined && items.length > 0 && (
        <ul className={styles.list}>
          {items.map((item) => {
            const isNew = fresh.has(item.id);
            return (
              <li key={item.id}>
                <article
                  className={cx(styles.item, isNew && styles.itemNew)}
                  aria-labelledby={`n-${item.id}`}
                  dir={dirOf(item.title)}
                >
                  <span className={styles.head}>
                    <span className={styles.title} id={`n-${item.id}`} dir="auto">
                      {item.title}
                    </span>
                    <time className={styles.time} dateTime={item.createdAt} dir="ltr">
                      {relativeTime(item.createdAt, now)}
                    </time>
                  </span>
                  <span className={styles.body} dir="auto">
                    {item.body}
                  </span>
                  {isNew && (
                    <span className={styles.mark}>
                      <span className={styles.dot} aria-hidden="true" />
                      {t('inbox.new')}
                    </span>
                  )}
                  <NotificationAction view={actionView(item, links.hosts, links.answered)} onOpen={onOpen} />
                </article>
              </li>
            );
          })}
        </ul>
      )}
    </Sheet>
  );
}
