/**
 * Whether Today's one-line messages want to show, apart from the banners
 * that draw them: the card that suggests another surface (NudgeSlot) shares
 * their place and stays away while one of them is up.
 */
import { getMeta } from '@/db/schema.js';
import { countPracticeDays, countWords, listNotebooks, loadSettings } from '@/db/repo.js';
import { notificationsAllowedHere, remindsHere } from '@/features/session/reminderOffer.js';
import { platform } from '@/lib/platform/index.js';
import { PLAY_LISTING_URL, safeExternalUrl } from '@/lib/externalLinks.js';
import { desktopOffer, isNewer, type UpdateLink } from '@/lib/updates.js';

/**
 * From this many days with practice Today may offer the reminder. The first
 * day already asked, right after the first word (onboarding v2's reminder
 * ask, or the first session's summary), so Today asks again only once the
 * learner has come back: a product rule, not a tunable.
 */
export const REMINDER_OFFER_MIN_PRACTICE_DAYS = 2;

/**
 * Whether to offer the reminder. Only the phone and desktop apps can deliver
 * one (`remindsHere`), and the desktop app only with its notifications on; only to
 * somebody who has no reminder, has not said no, has words to be reminded
 * of and has come back on a second day of practice. (It used to wait for the
 * getting-started list to be done, while that list held Today's corner; the
 * list moved to Settings → Help & about on 22 Oct 2026.)
 */
export async function shouldOffer(): Promise<boolean> {
  if (!remindsHere()) return false;
  const [settings, dismissed, days] = await Promise.all([
    loadSettings(),
    getMeta('reminderOfferDismissed'),
    countPracticeDays(REMINDER_OFFER_MIN_PRACTICE_DAYS),
  ]);
  if (dismissed || (settings?.reminderTime ?? '') !== '') return false;
  if (days < REMINDER_OFFER_MIN_PRACTICE_DAYS) return false;
  if (!(await notificationsAllowedHere())) return false;
  for (const notebook of await listNotebooks()) {
    if ((await countWords(notebook.id)) > 0) return true;
  }
  return false;
}

/** The update line: the newer version, and its buttons in the order to show them. */
export interface Offer {
  version: string;
  links: UpdateLink[];
}

/**
 * The newer build the update line offers, or null: sideloaded Android builds
 * and the desktop app only (the only copies that read the version file).
 */
export async function loadOffer(): Promise<Offer | null> {
  if (platform.env.embedded && platform.env.platform === 'desktop') return loadDesktopOffer();
  const [known, dismissed] = await Promise.all([getMeta('updateCheck'), getMeta('updateDismissed')]);
  if (known === null || !isNewer(known.version, platform.env.appVersion)) return null;
  if (dismissed === known.version) return null;
  // Inside the Android app the update comes from Google Play (owner,
  // 2026-10-10): the button opens the listing, a fixed address, and the
  // shell hands it to the system, which opens the Play app. Nothing in the
  // version file can change where it goes.
  if (platform.env.embedded && platform.env.platform === 'android') {
    const play = safeExternalUrl(PLAY_LISTING_URL, 'store');
    return play === undefined
      ? null
      : { version: known.version, links: [{ kind: 'download', url: play.href }] };
  }
  // Checked again here: an answer stored by an older build was never checked.
  const url = safeExternalUrl(known.url, 'update');
  if (url === undefined) return null;
  return { version: known.version, links: [{ kind: 'download', url: url.href }] };
}

/**
 * The desktop app's offer: worked out from the last answer each time, so it
 * follows this copy's own version the moment it is updated, and checked
 * against the version the learner put away.
 */
async function loadDesktopOffer(): Promise<Offer | null> {
  const [known, dismissed] = await Promise.all([getMeta('desktopRelease'), getMeta('updateDismissed')]);
  if (known === null) return null;
  const offer = desktopOffer(known.release, platform.env.appVersion);
  if (offer === null || offer.version === dismissed) return null;
  return offer;
}
