/**
 * Which card, if any, Today shows to suggest another surface. Pure: every
 * input is passed in, so each rule has a test.
 *
 * The rules are the marketer's study (marketing/research/2026-10-cross-promotion.md,
 * adopted 2026-10-07) and they are about restraint:
 *
 * - one card per app session, and none while another message (the reminder
 *   offer, an update, the confirm-your-address line) holds the slot;
 * - at most `perWeek` showings in any seven days, never the same card two
 *   sessions running, a card shown at most `lifetime` times, "Not now" for
 *   `snoozeDays`, "Don't show again" for good — all counted on the server,
 *   so they hold across devices;
 * - nothing in the first `quietDays` after sign-up, nothing for the holdout,
 *   nothing when the server turns the cards off;
 * - never a surface the account has used, anywhere, and never one the
 *   server has not released (Android "coming" until Play production, the
 *   desktop app "beta" until it is signed);
 * - each card waits for the behaviour that makes it useful.
 *
 * The numbers above come from the server (the cross_promotion flag). The
 * triggers' own thresholds below are the study's definition of each moment;
 * changing one changes what the card means, so they are named here, next to
 * the rule they belong to.
 *
 * The cards that offer an app (N2, N5, N6: "get the right app for this
 * device", owner 2026-10-17) also wait for a moment of success: the learner
 * has practised today, so the card is there when they come back to Today
 * from a finished session, never while they are about to start one. And
 * they wait for a notebook past "still small", so they never sit beside
 * "More ways to bring in words".
 */
import type { ApiNudgeId, ApiNudgeView, ApiSurface, ApiSurfaceStatus } from '@/api/types.js';
import { WAYS_IN_MAX_WORDS } from '@/features/getstarted/offer.js';
import { extensionStore, type Device } from '@/lib/platform/device.js';
import { appOffer, computerCardOffer, offersAnything } from './apps.js';
import type { Arrival, LocalSignals } from './state.js';

/** N1: words added by hand, and on how many different days. */
export const EXTENSION_MIN_WORDS = 10;
export const EXTENSION_MIN_DAYS = 3;
/** N4: days with practice, and words, before suggesting the computer. */
export const COMPUTER_MIN_PRACTICE_DAYS = 7;
export const COMPUTER_MIN_WORDS = 20;
/** N5: days with practice before suggesting the apps on a computer. */
export const PHONE_MIN_PRACTICE_DAYS = 3;
/** N6: the second day of practice in a phone's browser. */
export const ANDROID_BROWSER_MIN_PRACTICE_DAYS = 2;
/**
 * N2, N5, N6: the notebook has grown past "still small", the size below
 * which Today shows "More ways to bring in words" instead.
 */
export const APP_MIN_WORDS = WAYS_IN_MAX_WORDS;
/** N7: days with Lex, or uses of Paste a text, before suggesting ChatGPT or Claude. */
export const CONNECTOR_MIN_LEX_DAYS = 3;
export const CONNECTOR_MIN_PASTES = 3;

/** The order cards are tried in, until there is data to rank them by connect rate. */
export const NUDGE_ORDER: readonly ApiNudgeId[] = [
  'extension',
  'on_your_computer',
  'connector',
  'on_your_phone',
  'android_browser',
  'desktop_safari',
  'desktop_power',
];

export interface NudgeInput {
  view: ApiNudgeView;
  surfaces: readonly ApiSurfaceStatus[];
  device: Device;
  signals: LocalSignals;
  arrival: Arrival | undefined;
  /** This app session's id. */
  session: string;
  /** True while the reminder offer, an update or the confirm-address line is on Today. */
  slotTaken: boolean;
  now: Date;
}

const DAY_MS = 86_400_000;

function used(surfaces: readonly ApiSurfaceStatus[], ...ids: ApiSurface[]): boolean {
  return surfaces.some((s) => ids.includes(s.surface) && s.everUsed);
}

function live(surfaces: readonly ApiSurfaceStatus[], id: ApiSurface): boolean {
  return surfaces.find((s) => s.surface === id)?.release === 'live';
}

/** A moment of success for the app cards: practice done today, in a notebook past its first words. */
function succeeded(signals: LocalSignals): boolean {
  return signals.practisedToday && signals.words >= APP_MIN_WORDS;
}

/** Whether a card's moment has come, on this device, for this account. */
export function triggered(id: ApiNudgeId, input: NudgeInput): boolean {
  const { device, signals, surfaces, view } = input;
  const computerBrowser = device.shell === 'web' && !device.mobile;
  switch (id) {
    case 'extension':
      return (
        computerBrowser &&
        extensionStore(device) !== undefined &&
        live(surfaces, 'extension') &&
        !used(surfaces, 'extension') &&
        signals.typedWords >= EXTENSION_MIN_WORDS &&
        signals.typedDays >= EXTENSION_MIN_DAYS
      );
    case 'on_your_computer':
      // Shown inside the phone app, so it waits for the app to be public.
      return (
        device.shell === 'android' &&
        live(surfaces, 'android') &&
        live(surfaces, 'extension') &&
        !used(surfaces, 'extension', 'desktop') &&
        signals.practiceDays >= COMPUTER_MIN_PRACTICE_DAYS &&
        signals.words >= COMPUTER_MIN_WORDS
      );
    case 'connector':
      return (
        (live(surfaces, 'chatgpt') || live(surfaces, 'claude')) &&
        !used(surfaces, 'chatgpt', 'claude', 'claude_code') &&
        (view.lexDays >= CONNECTOR_MIN_LEX_DAYS ||
          signals.pasteUses >= CONNECTOR_MIN_PASTES ||
          input.arrival !== undefined)
      );
    case 'on_your_phone':
      // The apps, from a computer: the phones' stores, and the desktop app
      // on a Mac or a Windows PC, whichever of them may be offered.
      return (
        computerBrowser &&
        offersAnything(computerCardOffer(device, surfaces)) &&
        signals.practiceDays >= PHONE_MIN_PRACTICE_DAYS &&
        succeeded(signals)
      );
    case 'android_browser':
      // The app for this phone, from its browser: Google Play on Android,
      // the App Store on an iPhone or iPad (off until `releases.ios` is live).
      return (
        device.shell === 'web' &&
        device.mobile &&
        appOffer(device, surfaces).phones.length > 0 &&
        signals.practiceDays >= ANDROID_BROWSER_MIN_PRACTICE_DAYS &&
        succeeded(signals)
      );
    case 'desktop_safari':
      return (
        computerBrowser &&
        device.os === 'mac' &&
        device.browser === 'safari' &&
        appOffer(device, surfaces).desktop === 'mac' &&
        signals.typedWords >= EXTENSION_MIN_WORDS &&
        signals.typedDays >= EXTENSION_MIN_DAYS &&
        signals.words >= APP_MIN_WORDS
      );
    case 'desktop_power':
      // Needs "extension used on 5 of the last 14 days", which nothing
      // records yet; it stays off until that signal exists.
      return false;
    case 'kindle':
      // Needs "words from a book", which nothing marks yet.
      return false;
  }
}

/** Whether a card may be shown at all now, whatever its trigger says. */
function available(id: ApiNudgeId, input: NudgeInput): boolean {
  const state = input.view.nudges.find((n) => n.id === id);
  if (state === undefined) return false;
  if (state.retired || state.dismissedAt !== undefined) return false;
  if (state.shownCount >= input.view.rules.lifetime) return false;
  if (state.snoozedUntil !== undefined && Date.parse(state.snoozedUntil) > input.now.getTime()) return false;
  return true;
}

/**
 * The card to show now, or null.
 *
 * A card already shown in this session is kept for the rest of it (the
 * session's one slot), until it is acted on or stops being available.
 */
export function pickNudge(input: NudgeInput): ApiNudgeId | null {
  const { view, now, session } = input;
  if (!view.enabled || view.holdout) return null;
  if (now.getTime() < Date.parse(view.signedUpAt) + view.rules.quietDays * DAY_MS) return null;

  const thisSession = view.recentShows.find((show) => show.session === session);
  if (thisSession !== undefined) {
    const state = view.nudges.find((n) => n.id === thisSession.id);
    const actedOn =
      state === undefined ||
      state.dismissedAt !== undefined ||
      (state.snoozedUntil !== undefined && Date.parse(state.snoozedUntil) > now.getTime()) ||
      (state.tappedAt !== undefined && Date.parse(state.tappedAt) >= Date.parse(thisSession.at));
    return actedOn ? null : thisSession.id;
  }

  if (input.slotTaken) return null;
  if (view.recentShows.length >= view.rules.perWeek) return null;

  for (const id of NUDGE_ORDER) {
    // Never the same card two sessions running.
    if (view.lastShown?.id === id) continue;
    if (available(id, input) && triggered(id, input)) return id;
  }
  return null;
}
